E["npc:ayessa-dawnsinger"] = {t="npc",n="Ayessa Dawnsinger",z="zephras",s="In Valanaar on Zephras Isle, Ayessa Dawnsinger guides the Horde aligned Skyborne. She leads the Windshapers through their trials and politics.",h="In Valanaar on Zephras Isle, Ayessa Dawnsinger guides the Horde aligned Skyborne.",sec={{t="Leader of the Windshapers",b="From Valanaar on Zephras Isle, Ayessa Dawnsinger leads the Windshapers, the Skyborne aligned with the Horde. She directs their efforts across the island as they face outside threats and divisions among themselves. She guides them through alliances in Kalimdor and beyond, with their survival at stake.",sp=0},{t="The Struggle for Zephras",b="Ayessa Dawnsinger sends trusted champions to resolve conflicts on Zephras Isle. They face rogue constructs and hostile figures such as Lorthuna while the Skyborne confront their fate. Through political and physical struggles, Ayessa guides the Windshapers and keeps their voice and strength respected within the Horde.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger leads the Windshapers, the Horde aligned Skyborne on Zephras Isle.",al={"ayessa lore","who is ayessa","ayessa dawnsinger background"},it="identity"},{q="Where can Ayessa Dawnsinger be found?",a="Ayessa Dawnsinger can be found in Valanaar on Zephras Isle.",al={"where is ayessa","ayessa location","ayessa dawnsinger map"},it="place",gp=true},{q="What are the Windshapers?",a="The Windshapers are the Skyborne faction aligned with the Horde. Ayessa Dawnsinger guides them from Valanaar.",al={"windshapers faction","who are windshapers"},it="people"},{q="What is Ayessa's role in local quests?",a="Ayessa Dawnsinger gives work concerning the island's defense, including investigating rogue constructs, confronting Lorthuna, and shaping Zephras's future.",al={"ayessa quests","ayessa questline"},it="purpose",gp=true},{q="Whose side is Ayessa Dawnsinger on?",a="Ayessa Dawnsinger stands firmly aligned with the Horde. As the leader of the Windshapers, she guides the Horde-allied Skyborne faction operating out of Valanaar on Zephras Isle, directing their efforts and rallying Horde champions to her cause.",al={"ayessa dawnsinger faction","is ayessa horde or alliance","ayessa allegiance"},it="side",add="53a49c44"},{q="Who is Ayessa Dawnsinger tied to?",a="Ayessa Dawnsinger is directly tied to the Windshapers, the faction of Horde Skyborne whom she leads. Based in Valanaar, she coordinates their operations and orchestrates resistance against their local adversaries across Zephras Isle.",al={"ayessa dawnsinger faction ties","ayessa connections","who does ayessa work with"},it="ties",add="e31c8ea2"}},ang={["faction:Horde"]="For the Horde, Ayessa Dawnsinger is a key Skyborne ally and a point of contact on Zephras Isle.",["race:Skyborne"]="As a Skyborne, you can see in Ayessa Dawnsinger the path of those who stand with the Horde to secure their future."},kw={"ayessa","dawnsinger","horde","skyborne","valanaar","windshapers","zephras"},rel={"topic:skyborne","zone:zephras","topic:horde","quest:93746"},src={"Ayessa Dawnsinger"}}
E["npc:halaan-hawk-eye"] = {t="npc",n="Halaan Hawk-Eye",z="zephras",s="From Thendal Village, Halaan Hawk-Eye watches Zephras Isle’s anchor pylons. Though he lacks many Skyborne gifts, his keen natural vision helps him warn visitors as the pylons’ magic falters.",h="From Thendal Village, Halaan Hawk-Eye watches Zephras Isle’s anchor pylons.",sec={{t="A Watchman Without Magic",b="From the tower above Thendal Village, Halaan Hawk-Eye keeps watch. Many Skyborne can draw on the ley lines beneath Zephras Isle or see between worlds with mystical skysight. Halaan has neither gift. So he trusts his sharp natural senses, scanning the horizon for the island’s anchor pylons and calling attention to their increasingly volatile, inconsistent arcane energies.",sp=0}},faq={{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye watches from the tower above Thendal Village on Zephras Isle. He scans the surrounding land and warns visitors about the erratic magic afflicting the island’s anchor pylons.",al={"halaan hawkeye","who is halaan","thendal watchtower npc"},it="identity"},{q="What makes Halaan different from other Skyborne?",a="Unlike many Skyborne, Halaan cannot see between worlds with mystical skysight or harness the ley lines beneath Zephras Isle. He relies on keen eyesight and natural observation.",al={"halaan abilities","can halaan use magic","halaan skysight"}},{q="Why is Halaan worried about the anchor pylons?",a="Halaan has noticed the distant anchor pylons’ magic growing erratic and inconsistent. He does not know how this threatens Zephras Isle’s stability.",al={"what is wrong with the pylons","anchors of zephras problem"},it="wants"},{q="Where can I find Halaan Hawk-Eye?",a="You can find Halaan Hawk-Eye atop the wooden watchtower in Thendal Village on Zephras Isle. He looks out over the horizon.",al={"where is halaan","halaan location"},it="place",gp=true},{q="Whose side is Halaan Hawk-Eye on?",a="Halaan is one of the Skyborne, standing with his fellow kin on Zephras Isle. Lacking the innate ley line sorcery and otherworldly skysight of his peers, he still serves his people faithfully by keeping watch over Thendal Village and alerting travelers to the creeping instability threatening their homeland.",al={"halaan faction","halaan hawk eye side","who does halaan serve"},it="side",add="d6a0f6c4"},{q="Why is Halaan Hawk-Eye stationed at the watchtower?",a="Halaan keeps watch atop the Thendal Village tower because he cannot draw upon the local ley lines or use magical skysight like other Skyborne. Instead, he uses his sharp natural vision to survey Zephras Isle, monitoring the distant anchor pylons as their magical stability begins to falter.",al={"why is halaan hawk-eye here","why is halaan at the watchtower","halaan location reason"},it="why_here",add="e8313a77"}},ang={["race:Skyborne"]="As a Skyborne, you can see how those without a natural affinity for ley line magic or skysight still serve their community through vigilance and martial duty."},kw={"anchor pylon","halaan","hawk-eye","skyborne","skysight","thendal village","zephras isle"},rel={"quest:94414","zone:zephras","topic:skyborne"},src={"Halaan Hawk-Eye"}}
E["npc:rorian-the-dayseeker"] = {t="npc",n="Rorian the Dayseeker",z="zephras",s="In Thendal Village, young Skyborne look to Rorian the Dayseeker as they approach adulthood. He teaches them to survive, honor tradition, and serve their island home.",h="In Thendal Village, young Skyborne look to Rorian the Dayseeker as they approach adulthood.",sec={{t="Elder of Thendal Village",b="In Thendal Village on Zephras Isle, Rorian the Dayseeker guides young Skyborne through the passage into adulthood. Under his calm instruction, fledglings face a traditional rite that marks their readiness to defend and support their island home.",sp=0},{t="Guiding the New Callings",b="Rorian also directs promising fledglings toward callings suited to their talents. Aspiring warriors, hunters, rogues, mages, shamans, and druids find trainers across the isle through his guidance. When elemental disturbances trouble the island, he alerts them and teaches them to preserve its balance.",sp=0}},faq={{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder Skyborne leader in Thendal Village on Zephras Isle. He guides young Skyborne through their early trials.",al={"who is rorian","rorian role","what does rorian do"},it="identity"},{q="Where can Rorian the Dayseeker be found?",a="Rorian is in Thendal Village, the Skyborne starting settlement on Zephras Isle.",al={"where is rorian","rorian location","find rorian"},it="place",gp=true},{q="What is Rorian's role in the Skyborne coming of age?",a="Rorian guides fledglings through rites of passage into adulthood. He tests their mettle and attunement to island life, then sends them to serve the wider settlement.",al={"rorian coming of age","skyborne trial mentor"},it="purpose"},{q="How does Rorian direct new trainees into their classes?",a="Once a novice proves their worth, Rorian points them toward advanced training as a warrior, hunter, rogue, mage, shaman, or druid.",al={"class quests rorian","choosing a class with rorian"},gp=true},{q="Why does Rorian send adventurers to deal with elementals?",a="Rorian sends capable initiates to investigate and calm elemental unrest. Their efforts help preserve harmony in Thendal Village and the surrounding wildlands.",al={"elemental unrest rorian","why fight elementals zephras"},it="motive"},{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales is on Zephras Isle. Rorian directs fledglings to them as they progress through their island responsibilities and training.",al={"aetheen rorian","aetheen of the gales"},it="ties"},{q="Whose side is Rorian the Dayseeker on?",a="Rorian serves his own people, the Skyborne of Zephras Isle. Stationed within Thendal Village, his loyalty rests firmly with the island's community as he prepares the next generation of Skyborne youth to step out into the world and face whatever threats imperil their homeland.",al={"rorian faction","who does rorian serve","rorian allegiance"},it="side",add="60e564c2"},{q="What does Rorian the Dayseeker want?",a="Rorian is committed to guiding fledgling Skyborne through their traditional rites of passage. He wants each young trainee to embrace their calling—whether martial, arcane, or natural—while ensuring the village is safeguarded against dangerous elemental turmoil.",al={"rorian goal","what is rorian trying to do","rorian dayseeker purpose"},it="wants",add="ec1df735"},{q="Why is Rorian the Dayseeker in Thendal Village?",a="Rorian remains in Thendal Village to oversee the coming-of-age trials for Skyborne initiates. From here, he monitors the island's affairs, directs novices toward specialized trainers, and dispatches capable hands to restore balance when elemental agitation flares up nearby.",al={"why is rorian here","why is rorian in thendal village","rorian location why"},it="why_here",add="c3a8f075"}},ang={["race:Skyborne"]="As a fledgling Skyborne, you meet Rorian the Dayseeker at the first threshold of duty and tradition. He guides your passage into adulthood in Thendal Village.",["class:Warrior"]="Rorian sees your dedication as an aspiring warrior and points you toward mentors who teach battlefield discipline.",["class:Mage"]="As a novice arcanist, you find an understanding guide in Rorian. He directs you toward teachers who can hone your magical potential.",["class:Shaman"]="Rorian stresses the island's harmony and sends you to soothe agitated elementals and connect with ancestral traditions."},kw={"dayseeker","fledgling","mentor","rorian","skyborne","thendal","zephras"},rel={"zone:zephras","topic:skyborne","quest:92460","quest:92461","quest:92464","quest:92469","quest:92471","quest:92474"},src={"Rorian the Dayseeker"}}
E["npc:ventaari-brightwish"] = {t="npc",n="Ventaari Brightwish",z="zephras",s="In Thendal Village, Ventaari Brightwish welcomes travelers from across Azeroth and offers them The Gift of Skysight.",h="In Thendal Village, Ventaari Brightwish welcomes travelers from across Azeroth and offers them The Gift of...",sec={{t="A Dweller of Thendal Village",b="Ventaari Brightwish welcomes newcomers to Thendal Village on Zephras Isle. As a Skyborne resident, she helps visitors from both the Alliance and the Horde. Through The Gift of Skysight, Ventaari introduces them to her people's traditions.",sp=0}},faq={{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish lives in Thendal Village on Zephras Isle. She greets visitors and offers The Gift of Skysight.",al={"ventaari","who is ventaari","ventaari brightwish"},it="identity"},{q="Where can I find Ventaari Brightwish?",a="Find Ventaari Brightwish in Thendal Village on Zephras Isle.",al={"ventaari location","where is ventaari","thendal village ventaari"},it="place",gp=true},{q="Is Ventaari hostile to the Horde or Alliance?",a="No. Ventaari Brightwish speaks with adventurers from both the Alliance and the Horde.",al={"ventaari faction","is ventaari friendly","can horde talk to ventaari"},it="side"}},ang={["race:Skyborne"]="As a Skyborne in Thendal Village, Ventaari Brightwish helps visitors learn about the culture and ways of Zephras Isle."},kw={"brightwish","skyborne","skysight","thendal village","ventaari","zephras isle"},rel={"zone:zephras","quest:92598","topic:skyborne","topic:alliance","topic:horde"},src={"Ventaari Brightwish"}}
E["quest:92460"] = {t="quest",n="Coming of Age",z="zephras",s="In Thendal Village, young Skyborne begin the rite that welcomes them into service to the shen'dorei. Ailee Farheart leads them to Rorian the Dayseeker, who gives each initiate an ancestral relic and hears their pledge to aid their people.",h="In Thendal Village, young Skyborne begin the rite that welcomes them into service to the shen'dorei.",sec={{t="A Rite of Passage",b="Ailee Farheart guides young Skyborne from Thendal Village toward adulthood. They travel just west to the greatfather tree, where the village elder waits. For the shen'dorei, the rite marks a passage into adulthood and a pledge to serve their community. Local troubles are rising.",sp=0},{t="The Ancestral Relic",b="At the entrance to the greatfather tree, Rorian the Dayseeker leads the ceremony. He gives each initiate an ancestral relic, an heirloom passed through generations of shen'dorei. The relic is a token of the winds of home. It stays with its bearer until their ashes are scattered to the breeze.",sp=0}},faq={{q="What is the purpose of the Coming of Age ceremony?",a="The ceremony marks young Skyborne's passage into adulthood, welcomes them into service for the shen'dorei, and grants them an ancestral heirloom.",al={"why coming of age","coming of age purpose","skyborne rite of passage"},it="purpose"},{q="Who initiates the quest?",a="Ailee Farheart welcomes you in Thendal Village on Zephras Isle and guides you to meet the village leadership.",al={"who gives coming of age","where does coming of age start","ailee farheart location"},gp=true},{q="Who do you report to for the ritual?",a="Rorian the Dayseeker, leader of Thendal Village, waits at the entrance to the greatfather tree just west of the settlement.",al={"who is rorian","where is rorian","rorian the dayseeker location"},gp=true},{q="What relic is bestowed during the ceremony?",a="Rorian gives you an inherited relic carried through generations of shen'dorei. Tradition says it stays with you until death, then passes to the next generation.",al={"what is the relic","skyborne relic","what do you get"},it="item"},{q="What does 'shen'dorei' mean in this context?",a="Rorian uses 'shen'dorei' to refer to the Skyborne, recalling their complex history, shared trials, and enduring identity on Zephras Isle.",al={"who are the shendorei","shendorei meaning","skyborne shendorei"},it="people"},{q="Where does your journey lead immediately after this?",a="After your rite of passage, Rorian directs you to local matters threatening the island, beginning with Harmony in Balance and Infestation Investigation.",al={"what quest is next","next steps after coming of age","after rorian"},it="next_step",gp=true},{q="Why does Ailee Farheart send you to Rorian?",a="Ailee Farheart sees you ready to take your place among your people. As a young shen'dorei reaching adulthood, you only experience this milestone once in your life. Thendal Village has eagerly anticipated your arrival and needs your help, but before you can step forward to shoulder responsibility for your community, tradition demands that you first present yourself to village leader Rorian the Dayseeker for the rite of passage.",al={"why does ailee want this done","ailee farheart motive","why send to rorian"},it="motive",add="39b489c8"}},ang={["race:Skyborne"]="As a Skyborne, you enter adulthood bearing a sacred family heirloom wherever the winds carry you."},kw={"ailee farheart","coming of age","rorian the dayseeker","shen'dorei","skyborne","thendal grove","thendal village","zephras isle"},rel={"zone:zephras","npc:rorian-the-dayseeker","topic:skyborne"},m={start="Ailee Farheart",["end"]="Rorian the Dayseeker",level="1",id=92460},src={"Coming of Age (Forever)"},fv=true}
E["quest:92461"] = {t="quest",n="Harmony in Balance",z="zephras",s="On Zephras Isle, Rorian the Dayseeker gives fledgling adventurers an early rite of duty. You thin the vuldren in Thendal Grove to protect the island’s natural balance, for its beasts feel magic shifting in the winds.",h="On Zephras Isle, Rorian the Dayseeker gives fledgling adventurers an early rite of duty.",sec={{t="Tending the Grove",b="In Thendal Grove, vuldren have grown too numerous for the island to sustain. Their numbers threaten the environmental harmony that supports Zephras Isle’s wildlife. Rorian the Dayseeker gives young protectors the duty of thinning the herd before it strains the grove and the life around it.",sp=0},{t="Winds of Unrest",b="Vuldren are usually docile, yet the beasts of Zephras Isle are sensitive to the island’s atmosphere. When magic carried on the winds falls out of balance, they respond sharply. Keeping their numbers in check helps prevent them from becoming unpredictable and dangerous pests.",sp=0}},faq={{q="Why do the vuldren need to be culled?",a="The vuldren population in Thendal Grove has surged beyond sustainable numbers. Left unchecked, they could exhaust local resources and upset the balance that sustains the grove’s other inhabitants.",al={"why kill vuldren","vuldren overpopulation","thendal grove vuldren"},it="motive"},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide and mentor on Zephras Isle. He oversees young adventurers’ training and teaches them to care for their home through great crises and everyday stewardship.",al={"rorian lore","who is rorian"},it="identity"},{q="What makes the vuldren act up?",a="Vuldren are usually docile, but Zephras Isle’s native beasts sense when magic in the island’s winds falls out of balance. That shift can change their behavior.",al={"why are vuldren aggressive","vuldren behavior"},it="threat"},{q="Where does this task take place?",a="You carry out the work in Thendal Grove, just east and southeast of the settlement on Zephras Isle.",al={"thendal grove location","where is thendal grove"},it="place"},{q="What lesson is Rorian trying to teach?",a="Rorian teaches that protecting your home can demand difficult measures. A guardian sometimes has to take a firm guiding hand to restore natural order.",al={"rorian lesson","meaning of harmony in balance"},it="purpose"},{q="What should be done while hunting the vuldren?",a="Nearby, Elatrell Featherlight asks you to look into a swarm of pesky cirrusflies. You can investigate the infestation in the grove while hunting vuldren.",al={"other quests nearby","infestation investigation"},gp=true},{q="What are the juvenile vuldren you are hunting?",a="Juvenile vuldren are native creatures inhabiting Thendal Grove. Although generally docile and an essential part of the local ecosystem, their numbers have surged to unsustainable levels. In addition, local wildlife has begun sensing disturbances in the magic carried on the winds of Zephras, causing them to behave unpredictably if left unchecked.",al={"what are vuldren","juvenile vuldren","who are we hunting"},it="target",add="240c10a3"},{q="Why does Rorian send you instead of handling the cull himself?",a="Having just marked your coming of age, you are being tested with the practical responsibilities of maintaining Zephras. Rorian sees managing the mundane needs of Thendal Grove as a necessary duty and an important lesson: even when facing great uncertainty, protecting their homeland requires a guiding hand to preserve harmony.",al={"why send me","why does rorian need me","why me"},it="why_me",add="b29e78f0"}},ang={["class:Druid"]="As a druid, you know that thinning an overgrown vuldren population can protect the wider ecosystem.",["class:Hunter"]="As a hunter, you learn to manage herd numbers and watch how native beasts respond to changes around them."},kw={"harmony in balance","juvenile vuldren","rorian the dayseeker","thendal grove","vuldren","zephras","zephras isle"},rel={"npc:rorian-the-dayseeker","zone:zephras","quest:92462"},m={start="Rorian the Dayseeker",level="1",id=92461},src={"Harmony in Balance"},fv=true}
E["quest:92462"] = {t="quest",n="Infestation Investigation",z="zephras",s="In Thendal Grove, cirrusflies swarm the eastern woods. Ranger Elatrell Featherlight sends young defenders to thin their growing numbers before nearby settlements are at risk.",h="In Thendal Grove, cirrusflies swarm the eastern woods.",sec={{t="A Swarm in the Canopy",b="Local rangers report a sudden rise in cirrusflies along Thendal Grove’s eastern edge. One is a minor pest, but a swarm grows aggressive and destructive. So Ranger Elatrell Featherlight sends capable youths to cull the insects before they overwhelm the grove.",sp=0},{t="Early Steps of Service",b="After coming of age, young defenders help keep Zephras Isle safe. Clearing pests protects nearby settlements from outbreaks in the woods. Yet entrails and insects clinging to returning hunters show the swarm is far larger than first feared.",sp=0}},faq={{q="What is a cirrusfly?",a="Cirrusflies are winged insect pests native to Zephras Isle. Alone, they are small, but they multiply quickly and can form dangerous swarms in places like Thendal Grove.",al={"cirrusfly","cirrusflies","what are cirrusflies"},it="target"},{q="Who gives the quest Infestation Investigation?",a="Elatrell Featherlight gives the assignment. The ranger is stationed in Thendal Grove and watches the local wildlife and surrounding woods.",al={"quest giver","who starts it","elatrell featherlight"},it="identity"},{q="Where are the cirrusflies located?",a="Cirrusflies gather in the eastern and southeastern reaches of Thendal Grove on Zephras Isle. They are found among the foliage and young vuldren.",al={"where to find flies","cirrusfly location","thendal grove flies"},it="place",gp=true},{q="Why is culling the cirrusflies important?",a="A single cirrusfly poses little danger, but a swarm can grow dense enough to threaten travelers, consume local plants, and upset Thendal Grove’s balance.",al={"why kill flies","why cull cirrusflies","cirrusfly threat"},it="motive"},{q="What comes after Infestation Investigation?",a="After you thin the swarm and report to Elatrell Featherlight, you are sent toward the heart of the infestation to face the Cirrusfly Queen.",al={"next quest","what next","investigation follow up"},sp=1,it="next_step"},{q="Where does this quest fit into the early journey on Zephras?",a="The assignment comes right after the Coming of Age trial. It is one of the first combat duties given to newly recognized defenders of Zephras Isle.",al={"quest chain","when do i get this","level requirement"},it="origin"}},ang={["class:Hunter"]="As a hunter, you track cirrusflies darting among the trees and practice leading fast-moving targets through dense cover.",["class:Druid"]="As a druid, you help preserve Thendal Grove by addressing natural imbalances before aggressive swarms strip the woodland bare."},kw={"cirrusfly","elatrell featherlight","infestation","investigation","pesky cirrusfly","thendal grove","zephras"},rel={"quest:92463","zone:zephras"},m={start="Elatrell Featherlight",level="2",id=92462},src={"Infestation Investigation"},fv=true}
E["quest:92463"] = {t="quest",n="The Cirrusfly Queen",z="zephras",s="In Thendal Grove, cirrusflies threaten the rangers of Zephras Isle. Their swarm has spread far, so Elatrell Featherlight sends you to hunt its queen and thin the flies at their source.",h="In Thendal Grove, cirrusflies threaten the rangers of Zephras Isle.",sec={{t="Striking the Hive",b="You have seen that killing worker cirrusflies does little to curb the swarm spreading through Thendal Grove. Elatrell Featherlight sends you to the grove’s southeastern reaches, where the main hive lies. The queen directs the colony and heavier soldier drones guard her.",sp=0},{t="A Ranger's Burden",b="From afar, cirrusflies may seem like petty pests. Yet the larger breeds threaten anyone who passes beneath Zephras’s boughs. Hunt down the matriarch and withstand her guards, and you prove your skill in battle. Featherlight’s rangers will give you praise and respect.",sp=0}},faq={{q="Where is the Cirrusfly Queen located?",a="The Cirrusfly Queen nests in the southeastern corner of Thendal Grove on Zephras Isle, near the heart of the insect hive.",al={"queen location","where is cirrusfly queen","find the queen"},it="place",gp=true},{q="Why is slaying the worker flies not enough?",a="Hunting wandering workers only thins the swarm’s outer edges. While the queen lives, she breeds aggressive soldiers and replenishes the hive, keeping Thendal Grove in danger.",al={"why kill the queen","culling the hive"},it="motive"},{q="Who issues the hunt for the Cirrusfly Queen?",a="After the first reports from the forest confirm the severity of the cirrusfly infestation, Elatrell Featherlight sends you after the queen.",al={"who gives this quest","quest giver queen"},it="identity"},{q="What makes the queen more dangerous than regular cirrusflies?",a="Larger, more aggressive soldier drones guard the queen and defend the hive.",al={"queen danger","cirrusfly soldiers"},it="threat"},{q="What quest precedes this assignment?",a="The hunt follows Infestation Investigation, which first revealed how widely cirrusflies had spread through the grove.",al={"prerequisite quest","what comes before"},gp=true},{q="What role does Elatrell Featherlight serve in the area?",a="Elatrell Featherlight watches over wilderness security on Zephras Isle, tracks threats in the region, and teaches new adventurers woodland tracking and ranger duties.",al={"featherlight role","who is featherlight"},it="identity"},{q="What is the Cirrusfly Queen?",a="The Cirrusfly Queen is the matriarch at the heart of the infestation spreading through Thendal Grove. Lurking deep in the grove near the main hive, she directs the swarm and relies on aggressive soldier flies to guard her. Slaying the common workers will never halt the proliferation of these insects—only cutting down the queen will break the hive's hold on the forest.",al={"who is cirrusfly queen","what is the cirrusfly queen","cirrusfly queen target"},it="target",add="4d5b02bf"}},ang={["class:Hunter"]="As a hunter, tracking a hive queen and outmaneuvering her guards gives you an early trial in tracking and culling beasts. The local rangers’ praise is at stake.",["race:Skyborne"]="As a Skyborne, clearing invasive swarms from Thendal Grove helps protect Zephras Isle’s natural balance and keep its routes safe for travel."},kw={"cirrusfly","elatrell featherlight","hive","queen","soldier","thendal grove","zephras"},rel={"quest:92462","zone:zephras"},m={start="Elatrell Featherlight",level="3",id=92463},src={"The Cirrusfly Queen"},fv=true}
E["quest:92464"] = {t="quest",n="Elemental Unrest",z="zephras",s="Near the Thendal Standing Stones, lesser wind spirits have grown restless. Their sentient elemental benefactors have departed Zephras Isle, and Rorian the Dayseeker sends you into Thendal Grove to find his apprentice, Yala Windwatcher, and learn what troubles the breeze.",h="Near the Thendal Standing Stones, lesser wind spirits have grown restless.",sec={{t="A Change in the Wind",b="For generations, powerful wind spirits lived beside the people of Zephras. They were sentient, and they guided and protected the islanders. Now those elemental benefactors have departed, leaving Zephras in lasting imbalance. Without them to tend the air, simple sprites reflect the volatile feelings and forces that linger across the land.",sp=0},{t="The Thendal Standing Stones",b="Northeast of Rorian's post, the air near the ancient Thendal Standing Stones has turned hostile. The lesser wind spirits lack true self-awareness, so they act in reaction, not malice. Rorian sent his apprentice, Yala Windwatcher, to watch their erratic behavior from the grove's edge. She is to discover what unseen tension disturbs them.",sp=0}},faq={{q="Why are the wind sprites agitated?",a="Wind sprites grow turbulent when their surroundings fall out of balance. Unlike the island's former elemental benefactors, they lack true self-awareness and instinctively mirror nearby emotions, intentions, and magical forces.",al={"why are elementals mad","wind unrest cause","sprites angry"},it="conflict"},{q="Who are the elemental benefactors Rorian mentions?",a="The elemental benefactors were sentient, benevolent wind spirits who once lived alongside the people of Zephras. Since they departed, the island has suffered continuous unrest without their steadying influence.",al={"elemental benefactors","who left zephras","wind spirits zephras"},it="people"},{q="Where can I find Yala Windwatcher?",a="Yala Windwatcher is in Thendal Grove, northeast of Rorian's post, watching the agitated wind sprites near the Thendal Standing Stones.",al={"yala windwatcher location","where is yala","thendal grove apprentice"},it="place",gp=true},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide on Zephras Isle. He watches over the island's spiritual balance and studies disturbances among its local elementals.",al={"who is rorian","rorian dayseeker"},it="identity"},{q="What happens after finding Yala?",a="Speaking with Yala leads into an investigation of what causes the turbulence at the standing stones, beginning with Agitators.",al={"next quest","what comes after elemental unrest","yala follow up"},it="next_step",gp=true},{q="Are the wind sprites dangerous?",a="The wind sprites are simple, but their agitation makes them erratic and defensive. They react aggressively to intruders while the disturbance lasts.",al={"are sprites hostile","elemental danger"},it="threat"},{q="Why does Rorian the Dayseeker want this done?",a="Ever since the elemental benefactors departed, the region has slid from one crisis to another. Now, the wind manifestations around the Thendal Standing Stones are acting agitated. Because these lesser sprites simply mirror the turbulent emotions and intentions of nearby creatures, Rorian fears what might be unsettling them. He sent his apprentice Yala to observe the situation and needs you to consult her so they can determine the root of the disturbance.",al={"rorian motive","why send to yala","why rorian wants this"},it="motive",add="8058eaf6"}},ang={["class:Shaman"]="As a shaman, you can read the wind spirits' reflection of Zephras's emotional climate as a warning of deeper trouble in the land.",["race:Skyborne"]="As a Skyborne, you depend on Zephras Isle's skies. Since the elemental benefactors departed, those skies have grown unpredictable. Stay vigilant."},kw={"elemental unrest","rorian the dayseeker","thendal grove","thendal standing stones","wind sprites","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Yala Windwatcher",level="3",id=92464},src={"Elemental Unrest (quest)"},fv=true}
E["quest:92465"] = {t="quest",n="Agitators",z="zephras",s="On Zephras Isle, unrest in Thendal Grove draws Yala Windwatcher's concern. The Al'Aketh cult has stirred peaceful wind sprites into hostile elementals, and its converts now threaten the grove.",h="On Zephras Isle, unrest in Thendal Grove draws Yala Windwatcher's concern.",sec={{t="Disturbing the Grove",b="Cultists of Al'Aketh have pushed into Thendal Grove and stirred the wind spirits who dwell there. Once peaceful, the sprites now rage as roiling winds, threatening anyone who passes through.",sp=0},{t="A Painful Necessity",b="Yala Windwatcher asks you to subdue the enraged elementals and the Al'Aketh converts behind the unrest. Quieting the wind creatures may restore a fragile calm to the grove.\n\nYala grieves at the thought of shen'dorei blood shed among her own people. Yet while the cult remains, she sees little choice.",sp=0}},faq={{q="Who gives the quest Agitators?",a="Yala Windwatcher asks you for help near Thendal Grove on Zephras Isle.",al={"quest giver","who starts agitators","yala windwatcher"},it="identity"},{q="What is the Al'Aketh cult doing in Thendal Grove?",a="The Al'Aketh cult has moved into Thendal Grove and stirred its native wind spirits into a violent frenzy.",al={"what are cultists doing","why are alaketh here","alaketh convert purpose"},it="threat"},{q="What are the Roiling Winds?",a="Roiling Winds are native wind sprites of Zephras Isle, stirred by Al'Aketh cultists into aggressive elemental whirlwinds.",al={"roiling winds","wind spirits","wind elementals in thendal grove"}},{q="Why is Yala Windwatcher saddened by killing the converts?",a="Yala grieves at shedding shen'dorei blood because the converts are her own people, led astray by dangerous cult teachings.",al={"why does yala regret killing","shedding shendorei blood","yala completion quote"}},{q="What quest follows Agitators?",a="After you finish Yala Windwatcher's work, you are directed to continue your duties with Return to Rorian.",al={"what quest is next","agitators follow up","where do i go after agitators"},it="next_step"},{q="Where does this conflict take place?",a="The conflict centers on Thendal Grove, on Zephras Isle.",al={"agitators location","thendal grove zone","where is thendal grove"},it="place"},{q="Why does Yala Windwatcher want you to deal with the Al'Aketh cult?",a="Yala Windwatcher sees the Al'Aketh cult as a blight threatening the balance of the island. Their rituals have agitated the peaceful native wind sprites into violent Roiling Winds, endangering anyone who walks near Thendal Grove. To protect the land and prevent innocent lives from being lost, she must act quickly to disperse the frenzied elementals and drive the cult out.",al={"yala windwatcher motive","why fight cultists yala","why kill roiling winds"},it="motive",add="ae9ef6e2"},{q="Who are you sent to kill in Thendal Grove?",a="You are tasked with slaying Al'Aketh Converts and destroying the Roiling Winds. The converts are shen'dorei who have joined the Al'Aketh cult and established a foothold in Thendal Grove, meddling with the local elements. Their disruptive presence has agitated the once-peaceful local wind sprites, corrupting them into violent gusts of living air that assault anyone passing through.",al={"agitators targets","who do i kill in thendal grove","who are the targets agitators"},it="target",add="5a804844"}},ang={["class:Shaman"]="As a shaman, you see cultists drive natural wind sprites into a violent frenzy. The upheaval in elemental balance calls for intervention.",["class:Druid"]="As a druid, you see rogue cultists disturb Thendal Grove's natural harmony. The grove's native spirits urgently need defense."},kw={"agitators","al'aketh","al'aketh convert","roiling winds","shen'dorei","thendal grove","yala windwatcher","zephras isle"},rel={"zone:zephras","quest:92469"},m={start="Yala Windwatcher",level="3",id=92465},src={"Agitators"},fv=true}
E["quest:92469"] = {t="quest",n="Return to Rorian",z="zephras",s="Yala Windwatcher sends you to Thendal Grove with urgent news from the field. After you help drive back the agitators on Zephras Isle, she reports that the Al'Aketh have disturbed the local wind spirits.",h="Yala Windwatcher sends you to Thendal Grove with urgent news from the field.",sec={{t="A Dire Report",b="Yala Windwatcher remains on Zephras Isle to face the hostiles still there. She sends you to Thendal Grove with word that the Al'Aketh are no longer working only in the shadows.",sp=0},{t="Escalation at the Standing Stones",b="Rorian the Dayseeker says Thendal Grove's leaders have watched the Al'Aketh from a distance for some time. Now the cultists have stirred native wind spirits near the standing stones. That marks a troubling escalation, and the leaders can no longer watch from afar.",sp=1}},faq={{q="Who sends you to speak with Rorian?",a="After you help suppress the hostile agitators threatening the area, Yala Windwatcher sends you to report to Rorian.",al={"quest giver","who starts return to rorian","yala windwatcher"}},{q="Where is Rorian the Dayseeker located?",a="Rorian the Dayseeker is in Thendal Grove, where the grove's leaders oversee affairs on Zephras Isle.",al={"where is rorian","rorian location","thendal grove rorian"},it="place",gp=true},{q="Who are the Al'Aketh?",a="The Al'Aketh are a cult on Zephras Isle. The grove's leaders watched them quietly from afar, but their recent agitation of wind spirits near the standing stones has made them an active threat.",al={"what is the cult","who are al'aketh","al'aketh cult"},it="threat"},{q="Why was Rorian not surprised by the news?",a="Rorian and the grove's leaders already knew of the cult's movements across the island. Until now, they watched quietly instead of confronting the cult directly.",al={"did rorian know","rorian reaction","why unsurprising"},it="conflict"},{q="What happens after reporting back to Rorian?",a="After hearing your report and thanking you for aiding Thendal Grove, Rorian sends you to Aetheen of the Gales, a member of the Council of Elders who has been watching you.",al={"next quest","what follows return to rorian","after return to rorian"},sp=1,it="next_step"},{q="Why did Yala stay behind?",a="Yala Windwatcher stays at the conflict site to deal with any stragglers while sending you ahead with the urgent news.",al={"why yala stays","where did yala go","yala windwatcher role"},it="why_me"},{q="Why does Yala Windwatcher send you to Rorian?",a="Yala needs the leadership in Thendal Grove alerted immediately to the confirmed presence of the Al'Aketh cult. While she remains behind to finish dealing with stragglers in the field, Rorian the Dayseeker must be warned of the cult's escalations and their agitation of local spirits so the grove can coordinate a response.",al={"why report to rorian","yala windwatcher motive","why does yala want rorian informed"},it="motive",add="aa0b8ee2"}},ang={["class:Shaman"]="As a Shaman, you know the Al'Aketh's deliberate agitation of wind spirits threatens elemental balance.",["class:Druid"]="As a Druid, you share the duty to defend Thendal Grove and preserve peace in Zephras Isle's sacred grounds."},kw={"al'aketh","cult","rorian","standing stones","thendal grove","wind spirits","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras"},m={start="Yala Windwatcher",["end"]="Rorian the Dayseeker",level="4",id=92469},src={"Return to Rorian"},fv=true}
E["quest:92470"] = {t="quest",n="Foul Matriarch",z="zephras",s="In the caves south of Thendal Village, Aetheen of the Gales tests new initiates against the ursera. They must thin the packs and slay their den mother, Urs'anah, to prove they can face greater perils across Zephras Isle.",h="In the caves south of Thendal Village, Aetheen of the Gales tests new initiates against the ursera.",sec={{t="A Test of Resolve",b="Around Thendal Village, Aetheen of the Gales watches newcomers find their footing. When an initiate shows early skill, Aetheen sends them into the southern caves for a dangerous rite of passage. There, they thin the local ursera packs and face the broodmother who threatens the village's edge.",sp=0},{t="The Threat of Urs'anah",b="Local rangers know the ursera are fierce, but Urs'anah is the greatest threat to the haven. Deep in Thendal Cave, the formidable matriarch directs her scavengers and guards her lair. Her severed head proves an adventurer can face ferocious beasts and is ready to venture beyond the starting grove.",sp=0}},faq={{q="Who assigns the task to kill Urs'anah?",a="Aetheen of the Gales assigns the trial from Thendal Village. Aetheen watches promising newcomers noticed by local figures like Rorian, then tests their mettle with a dangerous hunt.",al={"who gives foul matriarch","foul matriarch quest giver","who is aetheen of the gales"},gp=true},{q="Where can Urs'anah and the ursera scavengers be found?",a="Urs'anah and the ursera scavengers dwell in caves south and southwest of Thendal Village, in the hills within Thendal Grove. The matriarch's den lies deep in the cavern.",al={"urs'anah location","where is ursanah","ursera cave zephras","thendal cave location"},gp=true},{q="What is an ursera?",a="Ursera are aggressive, bear-like predators native to the wilder crags of Zephras Isle. Their scavenging packs can make dens dangerously close to settlements like Thendal Village.",al={"what is an ursera","ursera lore","are ursera bears"}},{q="What does completing this hunt signify for an adventurer?",a="Slaying Urs'anah marks a rite of passage. By overcoming cultist interlopers and the grove's most dangerous wildlife, the hunter proves they are ready to leave Thendal Village's sanctuary and take on wider responsibilities across Zephras Isle.",al={"why kill ursanah","importance of foul matriarch"}},{q="Why does Aetheen of the Gales send you against the matriarch?",a="Aetheen of the Gales has been watching your progress and demands a test of your resolve. She needs to know if you possess the strength and fortitude to survive the far greater perils awaiting Zephras Isle. Felling the dangerous matriarch proves you are capable of stepping beyond the safety of Thendal Village and serving the island in deeper, more treacherous trials.",al={"why does aetheen want urs'anah dead","aetheen motive","why kill urs'anah"},it="motive",add="03aee340"},{q="What is the Head of Urs'anah used for?",a="The head serves as undeniable physical proof of the matriarch's demise. Urs'anah is a notorious den mother known to the local rangers, and Aetheen will accept nothing less than her severed head to verify that the dangerous beast has truly been put down.",al={"head of urs'anah use","why keep urs'anah head","head of ursanah purpose"},it="item",add="30b9798a"},{q="Who is Urs'anah?",a="Urs'anah is the fierce matriarch and den mother of the local ursera, dwelling within the caves south of Thendal Village. Known and feared by the island's rangers, she commands the scavenger pack, making her the primary threat among the grove's predatory beasts.",al={"who is ursanah","what is urs'anah","urs'anah lore"},it="target",add="a1adff34"}},ang={["race:Skyborne"]="As a Skyborne initiate, mastering ground predators like Urs'anah shows you can fend for yourself on land. You are ready to venture beyond your secluded beginnings.",["class:Hunter"]="As a Hunter, tracking a fierce matriarch in her cave tests your knowledge of beasts and your resolve."},kw={"aetheen of the gales","foul matriarch","thendal cave","thendal grove","thendal village","urs'anah","ursera","zephras isle"},rel={"quest:92471","quest:92473","zone:zephras"},m={start="Aetheen of the Gales",level="5",id=92470,ri={"Head of Urs'anah"}},src={"Foul Matriarch"},fv=true}
E["quest:92471"] = {t="quest",n="Aetheen of the Gales",z="zephras",s="On Zephras Isle, young adventurers who pass their first trials go to meet Aetheen of the Gales at Thendal Grove. There, the next generation faces her judgment.",h="On Zephras Isle, young adventurers who pass their first trials go to meet Aetheen of the Gales at Thendal...",sec={{t="A Measure of Potential",b="Young novices on Zephras Isle take on early duties that test their grit and spirit. The island's mentors watch for those ready to help defend their home. Rorian the Dayseeker notices youths prepared for greater responsibility.",sp=0},{t="The Wind-Reader of Thendal Grove",b="At Thendal Grove, Aetheen of the Gales reads the currents of the air. She belongs to the Council of Elders, which governs Zephras Isle, and assesses young shen'dorei as they come of age. Reporting to her takes you beyond minor duties along the island's perimeter and toward threats facing the community.",sp=0}},faq={{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales leads on Zephras Isle and serves on its Council of Elders. At Thendal Grove, she reads the winds and assesses young shen'dorei coming of age, judging whether they are ready to defend their home.",al={"who is aetheen","aetheen of the gales role","aetheen zephras"},it="identity"},{q="Why does Rorian send players to meet Aetheen?",a="After their early duties, Rorian the Dayseeker sends capable and resilient novices to Aetheen. She judges their skills and directs them toward greater challenges facing the island.",al={"why meet aetheen","rorian sends to aetheen","purpose of this quest"},it="motive"},{q="Where can Aetheen of the Gales be found?",a="Aetheen of the Gales can be found in Thendal Grove on Zephras Isle. There she reads the winds and oversees coming-of-age trials for local youths.",al={"aetheen location","where is aetheen","thendal grove aetheen"},it="place",gp=true},{q="What is the Council of Elders?",a="The Council of Elders governs the shen'dorei on Zephras Isle. Aetheen and the other council leaders guide their community's survival, leadership, and readiness.",al={"council of elders zephras","who rules zephras"},it="in_charge"},{q="What happens after reporting to Aetheen?",a="Once Aetheen judges a young adventurer ready to serve Zephras Isle, she assigns serious work against dangers in the local wilderness, including aggressive wildlife and foul matriarchs.",al={"next quest after aetheen","what does aetheen want"},it="next_step"},{q="What does 'coming of age' mean for shen'dorei on Zephras Isle?",a="For young shen'dorei on Zephras Isle, coming of age means proving themselves through physical and magical trials. They show an island elder like Aetheen that they can serve before taking on that duty.",al={"shen'dorei coming of age","zephras coming of age"},it="people"},{q="Why does Rorian need you specifically to go speak with Aetheen?",a="Your early tasks across the isle were quietly treated as trials to gauge your mettle. Zephras faces serious challenges, and its leaders need capable, spirited young shen'dorei who are coming of age to step forward and aid their people. Having proven your competence, Rorian has singled you out as someone ready for direct assessment by Elder Aetheen.",al={"why me aetheen of the gales","why does rorian pick me","why send me to aetheen"},it="why_me",add="d6e78b3c"}},kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendal grove","zephras isle"},rel={"quest:92469","npc:rorian-the-dayseeker","zone:zephras","quest:92460"},m={start="Rorian the Dayseeker",["end"]="Aetheen of the Gales",level="4",id=92471},src={"Aetheen of the Gales (quest)"},fv=true}
E["quest:92472"] = {t="quest",n="The Next Step",z="zephras",s="Elder Aetheen turns south after the beasts near Thendal Village are dealt with. The Al'Aketh Cult's zealots threaten Shen'dar Village.",h="Elder Aetheen turns south after the beasts near Thendal Village are dealt with.",sec={{t="Leaving Thendal Village",b="Elder Aetheen of the Gales sees danger growing across Zephras Isle. The predators and matriarchs of the northern wilderness have been dealt with, but that was only the lesser trouble. Outlying settlements still need defenders.",sp=0},{t="The Looming Shadow of the Cult",b="The Al'Aketh Cult is the chief danger in southern Zephras. Its ruthless zealots worship Al'Akir the Windlord, ruler of Skywall in the elemental realm. Their growing power threatens Shen'dar Village. Aetheen sends travelers south along the road, past ambushers in the highlands, to aid Constable Aonda's local guard.",sp=0}},faq={{q="Where does this journey lead?",a="The road runs south from Thendal Village through the Shen'dar Highlands to Shen'dar Village. Constable Aonda oversees the village's defense.",al={"where do i go","next hub","destination"},it="next_step"},{q="Who is Constable Aonda?",a="Constable Aonda holds civic and military authority in Shen'dar Village. The constable keeps order and protects the village from growing cultist threats.",al={"constable aonda","who is aonda"},it="identity"},{q="What is the Al'Aketh Cult?",a="The Al'Aketh are ruthless zealots on Zephras Isle who worship Al'Akir the Windlord, ruler of Skywall. Their growing power threatens the island's settlements.",al={"who are the al'aketh","al'aketh cult lore","cultists"},it="threat"},{q="Who is Al'Akir?",a="Al'Akir the Windlord rules the skies and commands Skywall. Air elementals revere him, and the Al'Aketh Cult worships him fanatically.",al={"who is alakir","windlord","skywall ruler"},it="power"},{q="Why does Elder Aetheen send travelers away from Thendal?",a="With the immediate threats around Thendal handled, Aetheen sends proven defenders to Shen'dar Village. The Al'Aketh Cult's advance endangers the island far more than the troubles around Thendal.",al={"why leave thendal","aetheen's goal"},it="motive"},{q="What hazards are along the road to Shen'dar Village?",a="The trail south crosses the Shen'dar Highlands. Al'Aketh Ambushers and rogue cult thugs harass travelers moving between the island's settlements.",al={"road hazards","traveling south","highland danger"},it="danger"}},ang={["race:Skyborne"]="For the Skyborne, facing the Al'Aketh means fighting elemental fanaticism that threatens settlements across their home on Zephras Isle.",["class:Shaman"]="As a shaman, you know the danger of mortals blindly worshiping elemental lords like Al'Akir. His volatile nature often demands servitude rather than balance."},kw={"aetheen of the gales","al'aketh cult","al'akir","constable aonda","shen'dar village","skywall","thendal village","zephras isle"},rel={"quest:92471","quest:92470","zone:zephras","quest:92544","quest:96627","topic:skywall"},m={start="Aetheen of the Gales",["end"]="Constable Aonda",level="5",id=92472},src={"The Next Step (Skyborne)"},fv=true}
E["quest:92473"] = {t="quest",n="Aggressive Encroachment",z="zephras",s="At the village, starving ursera now threaten the settlement. Valreaa Valewind calls for a cull after one beast nearly attacked a child at the elder tree.",h="At the village, starving ursera now threaten the settlement.",sec={{t="Desperate Predators",b="Ursera from dens southwest of the village have become dangerous to its people. A hungry adolescent reached the base of the central elder tree and nearly mauled a child at play. The settlement's rangers killed the beast before anyone was hurt.",sp=0},{t="Culling the Grove",b="The rangers believe hunger is driving ursera toward settled ground. They have ordered a cull of the scrawniest beasts prowling outside their dens in Thendal Grove. The Rangers of the Grove hope this will stop further incursions while they seek the cause of the wildlife's distress.",sp=0}},faq={{q="Who offers Aggressive Encroachment?",a="Valreaa Valewind, a leader among the rangers, offers the work. She watches over the grove and protects the nearby settlement from predatory beasts.",al={"who gives aggressive encroachment","quest giver","valreaa valewind quest"},gp=true},{q="Why are the ursera wandering so close to the village?",a="The ursera are starving and desperate. Hunger drives them far beyond their usual hunting grounds and into the settlement.",al={"why ursera attack","ursera aggression","why are ursera mad"},it="conflict"},{q="Where can the scrawny ursera be found?",a="Scrawny ursera prowl Thendal Grove southwest of the village, outside the den entrances rather than deep in the cave.",al={"where are scrawny ursera","ursera location","thendal grove bears"},it="target",gp=true},{q="What near-tragedy prompted this cull?",a="An adolescent ursera reached the elder tree in the middle of the village and tried to attack a young boy at play. Rangers killed the beast just in time to save him.",al={"ursera attack boy","what happened in the village","boy near elder tree"},it="motive"},{q="Why are the ursera behaving so erratically?",a="The ursera have grown unusually aggressive, but the rangers do not know what caused their food shortage or change in behavior.",al={"what changed with ursera","why ursera starving"},it="threat"},{q="What proof does Valreaa Valewind require?",a="Valreaa Valewind asks for six Scrawny Ursera Claws from the malnourished beasts prowling the grove, proof that the dangerous predators have been dealt with.",al={"what do I collect","aggressive encroachment objective"},it="item"}},ang={["class:Hunter"]="As a hunter, you know starving predators may abandon their natural wariness of settlements when famine drives them.",["class:Druid"]="As a druid, you can see the grove's balance shifting. The ursera's sudden aggression and malnutrition point to an unseen disturbance in the local ecosystem."},kw={"claws","elder tree","encroachment","scrawny ursera","thendal grove","ursera","valreaa valewind"},rel={"zone:zephras"},m={start="Valreaa Valewind",level="4",id=92473,ri={"Scrawny Ursera Claw"}},src={"Aggressive Encroachment"},fv=true}
E["quest:92474"] = {t="quest",n="Falling With Style",z="zephras",s="At Thendal Village, Myriaal Mistwake sends young Skyborne from a watchtower to test their falling skill. They glide down to Rorian the Dayseeker below.",h="At Thendal Village, Myriaal Mistwake sends young Skyborne from a watchtower to test their falling skill.",sec={{t="A Leap from the Tower",b="High above Thendal Village on Zephras Isle, Myriaal Mistwake invites young Skyborne to test their heritage with a daring leap. She urges newcomers to step from the watchtower ledge and trust their gift for slowing a fall. The practice is playful, yet it prepares them to walk on air when danger comes beyond the grove.",sp=0},{t="A Difference in Temperament",b="Myriaal delights in sudden descents that startle onlookers, while Rorian the Dayseeker favors caution. As novices glide down to land before him, he warns that careless use of their magic may leave travelers helpless in danger. Still, he accepts that controlled practice within the village has its place.",sp=0}},faq={{q="What is the purpose of this quest?",a="The leap lets novice Skyborne practice controlling a slow descent from a height with their natural magic.",al={"what does this quest do","falling with style purpose","why do this quest"},it="purpose"},{q="Who gives the quest and where?",a="Myriaal Mistwake gives it from the wooden watchtower above Thendal Village on Zephras Isle.",al={"quest giver","where to start falling with style","who gives falling with style"},it="origin",gp=true},{q="Who do you land in front of?",a="You land near Rorian the Dayseeker, whom Myriaal hopes to startle with the leap.",al={"who to land near","who is rorian","falling with style turn in"},it="target"},{q="Why is Rorian upset by the jump?",a="Rorian believes Skyborne should use their natural magic with discipline, not waste it on practical jokes that startle people.",al={"why is rorian mad","rorian reaction","why does rorian scold you"},it="conflict"},{q="What ability is being practiced?",a="You practice Walk on Air, the skyborne gift that slows a fall and prevents injury from landing.",al={"what ability is used","walk on air quest","skyborne racial ability"},it="power",gp=true},{q="Where does this take place?",a="The practice takes place in Thendal Village on Zephras Isle, the Skyborne's ancestral starting grounds.",al={"quest location","where is thendal village","what zone is this"},it="place",gp=true},{q="Why does Myriaal Mistwake have you jump from the watchtower?",a="Myriaal Mistwake treats the leap as a playful challenge to help you practice your innate ability to walk on air, but she also has a mischievous motive: she wants to startle Rorian the Dayseeker and get a good laugh out of seeing him worked up.",al={"why does myriaal want this","myriaal mistwake motive","why jump from tower"},it="motive",add="fb92945d"}},ang={["race:Skyborne"]="As a Skyborne, you learn to slow your fall and hear the debate over how carefully to use your natural wind-walking magic."},kw={"falling with style","myriaal mistwake","rorian the dayseeker","slow fall","thendal village","walk on air","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","topic:skyborne","zone:zephras"},m={start="Myriaal Mistwake",["end"]="Rorian the Dayseeker",level="2",id=92474},src={"Falling With Style (Skyborne)"},fv=true}
E["quest:92481"] = {t="quest",n="A Student of the Arcane",z="zephras",s="On Zephras Isle, Rorian the Dayseeker calls novice spellcasters to A Student of the Arcane. After newcomers prove their mettle, they review a Glowing Recall Crystal and report to Dorii Brightwhisper, the local mentor.",h="On Zephras Isle, Rorian the Dayseeker calls novice spellcasters to A Student of the Arcane.",sec={{t="A Message in Crystal",b="After helping with the troublesome vuldren near Thendal Grove, fledgling mages receive a curious artifact: a Glowing Recall Crystal. Dorii Brightwhisper, the island’s arcane instructor, left it behind. Its recorded message tests an initiate’s aptitude and welcomes them into deeper study of magic.",sp=0},{t="Rediscovering the Arcane",b="Dorii Brightwhisper says arcane mastery has slowly faded among their people. For millennia, they lived secluded high in the clouds. So Dorii sees each new practitioner as a pioneer who can recover lost knowledge and restore their people’s once-mighty magical heritage.",sp=0}},faq={{q="What is the Glowing Recall Crystal?",a="The Glowing Recall Crystal is a small magical focus that Dorii Brightwhisper entrusted to Rorian the Dayseeker. It holds an inscribed message introducing young apprentices to the basics of arcane communication.",al={"recall crystal","crystal message","what does the crystal do"},it="item"},{q="Who is Dorii Brightwhisper?",a="Dorii Brightwhisper is the resident mage trainer in the structure behind Rorian the Dayseeker in Thendal Grove on Zephras Isle. Dorii guides young mages seeking to reclaim their people’s ancient arcane traditions.",al={"who is dorii","mage trainer zephras","dorii location"},it="identity"},{q="Why has arcane magic waned among the people of Zephras?",a="As Dorii explains, arcane magic gradually declined over the thousands of years their people lived secluded high in the clouds. Dorii and other instructors train new novices to search for and recover what was lost.",al={"why did magic fade","skyborne arcane lore","lost arcane magic"},it="history"},{q="Who gives this quest?",a="Rorian the Dayseeker offers this in thendal grove on zephras isle after an aspiring mage completes Harmony in Balance.",al={"quest giver","who starts a student of the arcane","rorian quest"},gp=true},{q="Where can I find Dorii Brightwhisper?",a="Dorii Brightwhisper lives in the structure directly behind Rorian the Dayseeker within Thendal Grove.",al={"dorii brightwhisper location","where is the mage trainer","find dorii"},gp=true},{q="What prerequisite must be completed before starting this quest?",a="First, complete Harmony in Balance, which involves handling the local vuldren problem for Rorian the Dayseeker.",al={"prereq","prerequisites","what quest comes before"},gp=true},{q="Why does Rorian the Dayseeker send you to Dorii?",a="Rorian is simply passing along an urgent communication meant for you. While you were handling the nearby vuldren threat, Dorii Brightwhisper left a recall crystal specifically inscribed for your attention. Rorian ensures you receive the crystal and guides you directly to the grove's mage trainer so your arcane potential is not left untapped.",al={"why does rorian send you","rorian the dayseeker motive","why talk to dorii brightwhisper"},it="motive",add="1ed09f17"},{q="Why does Dorii Brightwhisper want to train you specifically?",a="Arcane arts have waned among your kin over millennia spent secluded in the clouds. Having proven your competence against local threats, Dorii Brightwhisper sees in you the raw capability required to help reclaim that lost heritage. She seeks aspiring mages who can actively explore and master the arcane, rather than letting ancient knowledge fade into memory.",al={"why you a student of the arcane","why train me","why does dorii want me"},it="why_me",add="ab250928"}},ang={["class:Mage"]="As a Mage, your tutelage under Dorii Brightwhisper begins here. Your path in magic helps restore long-lost arcane secrets from the clouds.",["race:Skyborne"]="As a Skyborne, you know that millennia of isolation among the clouds caused arcane traditions to wane. Young apprentices are central to renewing your people’s heritage."},kw={"dorii brightwhisper","glowing recall crystal","mage quest","rorian the dayseeker","student of the arcane","thendal grove","vuldren","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Dorii Brightwhisper",level="2",faction="Alliance",id=92481},src={"A Student of the Arcane"},fv=true}
E["quest:92482"] = {t="quest",n="The Way of the Hunter",z="zephras",s="Young hunters in Thendal Grove begin training after driving back the local vuldren. Now Rorian the Dayseeker summons them to meet Tai'ree Farsight and begin formal tutelage.",h="Young hunters in Thendal Grove begin training after driving back the local vuldren.",sec={{t="A Summons to the Hunt",b="After thinning the disruptive vuldren on Thendal Grove's outskirts, young hunters return to find their practical skills have drawn attention. Rorian the Dayseeker gives them a scribbled summons from Tai'ree Farsight, the grove's resident hunter trainer. For novice rangers preparing to explore Zephras Isle, the meeting turns their work from defending the island to learning martial skills and survival.",sp=0},{t="The Tutelage of Tai'ree",b="Near the center of the village, Tai'ree Farsight welcomes promising pupils with stern realism. Thriving in untamed nature demands sharp senses and lightning reflexes. Her guidance comes from her long years of experience, giving island trackers a foundation for honing their marksmanship and survival skills.",sp=0}},faq={{q="Who offers this task?",a="After you help Rorian the Dayseeker with the local vuldren infestation in 'Harmony in Balance', he offers this training in thendal grove on zephras isle.",al={"who gives the way of the hunter","quest starter","rorian quest"},it="identity"},{q="Who is Tai'ree Farsight?",a="Tai'ree Farsight is the resident hunter trainer near the center of Thendal Grove. She oversees the training and discipline of aspiring marksmen and island trackers.",al={"where is tai'ree","hunter trainer thendal grove","tai'ree farsight location"},it="identity"},{q="What is the purpose of the Scribbled Note?",a="The Scribbled Note is a message Tai'ree Farsight leaves while you are away dealing with the vuldren. It directs you to seek her out in the village square to begin advanced training.",al={"scribbled note","what does the note say","hunter note"},it="item"},{q="Where does this quest take place?",a="This takes place entirely within Thendal Grove, an outpost settlement on Zephras Isle.",al={"quest zone","hunter quest location","where is thendal grove"},it="place",gp=true},{q="What prerequisite must be completed before this quest?",a="Before meeting Tai'ree, you must complete 'Harmony in Balance' for Rorian the Dayseeker. There, you prove your initial competence by dealing with the aggressive vuldren near the grove.",al={"prereq for the way of the hunter","how to unlock","previous quest"},gp=true},{q="What does Tai'ree Farsight teach new hunters?",a="Tai'ree Farsight acts as your class trainer. Speaking with her introduces the core philosophy of island tracking and opens access to foundational hunter abilities and combat techniques.",al={"what does tai'ree do","why talk to tai'ree"},it="purpose"},{q="Why does Rorian the Dayseeker send you to Tai'ree Farsight?",a="While you were out handling the vuldren threat, the village's hunter trainer, Tai'ree Farsight, specifically left a note asking to speak with you. Rorian is simply passing along the message and directing you to where she waits in Thendal Grove so you can begin refining your martial skills.",al={"why does rorian send you","rorian motive way of the hunter","why visit tairee farsight"},it="motive",add="bb563a7d"}},ang={["class:Hunter"]="As a hunter on Zephras Isle, you begin formal training under Tai'ree Farsight."},kw={"hunter trainer","rorian the dayseeker","scribbled note","tai'ree farsight","the way of the hunter","thendal grove","vuldren","zephras"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Tai'ree Farsight",level="2",id=92482},src={"The Way of the Hunter"},fv=true}
E["quest:92483"] = {t="quest",n="At Home in the Shadows",z="zephras",s="Rorian sends you to meet Akeri Duskblade in Thendal Grove, where rogue training begins. The summons marks a change from village chores to stealth and combat.",h="Rorian sends you to meet Akeri Duskblade in Thendal Grove, where rogue training begins.",sec={{t="A Shady Invitation",b="Akeri Duskblade has noticed young rogues dealing with threats around Thendal Grove. The grove's rogue trainer avoids an open meeting in the settlement, so he sends a note through Rorian the Dayseeker. Though Akeri keeps his reasons close, Rorian sees that he knows the skills a rogue needs beyond the grove's sheltered bounds.",sp=0},{t="Lessons in the Watchtower",b="Akeri Duskblade waits in the Thendal Grove village watchtower. He judges each newcomer’s footing and awareness, then warns that careless steps beyond the grove can lead to an early grave. Passing his scrutiny begins formal training in stealth, precision, and survival on Zephras Isle.",sp=0}},faq={{q="Who gives the quest At Home in the Shadows?",a="Rorian the Dayseeker gives you Akeri's summons in thendal grove on zephras isle after you complete Harmony in Balance.",al={"who starts at home in the shadows","quest giver at home in the shadows","rorian quest"},gp=true},{q="Where can I find Akeri Duskblade?",a="Akeri Duskblade waits inside the village watchtower in thendal grove on zephras isle.",al={"akeri duskblade location","where is akeri duskblade","find akeri"},it="place",gp=true},{q="What is the Simple Note given during the quest?",a="Akeri Duskblade's Simple Note asks promising rogues to meet him. Read it before you speak with Akeri.",al={"simple note zephras","what is the note","read simple note"},it="item",gp=true},{q="Is this quest available to all classes?",a="No. The training is for rogues learning their trade in Thendal Grove.",al={"can non rogues do this quest","is at home in the shadows rogue only","class requirement"},gp=true},{q="What does Akeri Duskblade teach?",a="Akeri Duskblade teaches local rogues in Thendal Grove stealth, cunning, and bladecraft as they begin their journey across Zephras Isle.",al={"akeri duskblade role","who is akeri","rogue trainer thendal grove"},it="identity",gp=true},{q="What prerequisite quest must be completed first?",a="Complete Harmony in Balance for Rorian the Dayseeker first. Then he gives you Akeri's note.",al={"at home in the shadows prerequisite","previous quest","unlock at home in the shadows"},gp=true},{q="Why does Rorian the Dayseeker send you to Akeri Duskblade?",a="After proving your capability by handling the local vuldren threat, Rorian is simply passing along a summons. Akeri Duskblade, the grove's resident rogue trainer, specifically asked to see you and left a note for your attention. Rorian recognizes that a fledgling rogue needs proper tutelage from someone suited to the craft, playfully noting that you and the shady Duskblade will likely get along.",al={"rorian motives","why send to akeri","why talk to akeri duskblade"},it="motive",add="776f9cb3"},{q="Why does Rorian need you to go instead of dealing with Akeri himself?",a="Akeri Duskblade asked for you personally, not Rorian or the grove's guardians. You have chosen the path of a rogue, and Akeri is the local mentor responsible for training those who operate from the shadows. The summons is meant to test your awareness, sharpen your instincts, and prepare you to survive beyond the safety of Thendal Grove.",al={"why me akeri duskblade","why does akeri want to see me","why rogue trainer wants me"},it="why_me",add="4629917d"}},ang={["class:Rogue"]="As a rogue, you begin formal training on Zephras Isle when you meet Akeri Duskblade in the Thendal Grove watchtower."},kw={"akeri duskblade","at home in the shadows","rogue quest","rogue trainer","rorian the dayseeker","simple note","thendal grove","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Akeri Duskblade",level="2",id=92483},src={"At Home in the Shadows"},fv=true}
E["quest:92484"] = {t="quest",n="Embracing the Elements",z="zephras",s="In Thendal Grove, Rorian the Dayseeker calls young shamans to begin their elemental training. Windshaper Boro’s message speaks of a silence between the people and the spirits of the winds.",h="In Thendal Grove, Rorian the Dayseeker calls young shamans to begin their elemental training.",sec={{t="A Summons to the Elements",b="Rorian the Dayseeker comes to you after you help with the vuldren around the village. Windshaper Boro left a humming recall crystal while you were away. Its message calls you to the center of the grove, where formal elemental instruction begins.",sp=0},{t="The Silent Winds",b="Windshaper Boro tells you the spirits of the four winds ended all communication years ago. They left behind the communion they once shared with the people. Now the shamans of Zephras study the natural world and train hard, hoping to bridge the silence and speak with the spirits again.",sp=0}},faq={{q="Who gives the quest Embracing the Elements?",a="After you help with the local vuldren problem, Rorian the Dayseeker sends you from thendal grove on zephras isle.",al={"embracing the elements quest giver","who starts embracing the elements"},gp=true},{q="Where is Windshaper Boro located?",a="Near the center of thendal grove on zephras isle, Windshaper Boro trains the settlement’s shamans.",al={"windshaper boro location","where is boro","find windshaper boro"},gp=true},{q="Why did the elemental spirits stop speaking to the people here?",a="Windshaper Boro says the spirits of the four winds stopped speaking and left the people years ago. The local shamans do not know why, but they study in hope of restoring that bond.",al={"why are the winds silent","spirits of the four winds silent","what happened to the wind spirits"},it="history"},{q="What is the Humming Recall Crystal?",a="Windshaper Boro left the humming recall crystal while you were away helping the settlement. Examining it signals that you are ready to begin elemental training under his guidance.",al={"humming recall crystal","recall crystal zephras"},it="item"},{q="What prerequisite quest leads to Embracing the Elements?",a="Harmony in Balance comes first. You deal with the vuldren disrupting the surrounding area.",al={"embracing the elements prequest","what comes before embracing the elements"},gp=true},{q="What role does Windshaper Boro play in Thendal Grove?",a="Windshaper Boro trains the shamans of Thendal Grove. He teaches new initiates about elemental communion and the natural world.",al={"what does boro do","windshaper boro role"},it="identity"},{q="Why does Rorian the Dayseeker send you to Windshaper Boro?",a="While you were out handling the grove's vuldren troubles, Windshaper Boro specifically left a recall crystal in Rorian's care for you. Rorian is simply passing along the crystal and directing you to Boro near the village center so you can begin learning how to walk the path of the elements.",al={"why does rorian want this done","rorian boro quest why","why examine humming recall crystal"},it="motive",add="52185878"}},ang={["class:Shaman"]="As a shaman, you meet Windshaper Boro for formal instruction and learn that the elemental winds have fallen silent. Shamans devote themselves to restoring communion with them.",["faction:Horde"]="As a Horde traveler on Zephras Isle, you encounter the island’s elemental callers and their struggle with the spirits. The spirits’ silence shapes their training."},kw={"embracing the elements","humming recall crystal","rorian the dayseeker","shaman","spirits of the four winds","thendal grove","windshaper boro","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Windshaper Boro",level="2",faction="Horde",id=92484},src={"Embracing the Elements"},fv=true}
E["quest:92485"] = {t="quest",n="A Student of Nature",z="zephras",s="On Zephras Isle, A Student of Nature begins with a summons to novice druids. After they help restore local harmony, Xyton Silverwind calls them beneath the boughs of Thendal Grove to learn the isle's natural balance.",h="On Zephras Isle, A Student of Nature begins with a summons to novice druids.",sec={{t="A Summons from the Grove",b="After local disturbances caused by overzealous wildlife are resolved, Rorian the Dayseeker brings a personal summons to young initiates. The folded parchment was left by Xyton Silverwind. It invites aspiring druids to step forward and study the deeper mysteries of the wild, for their natural talents have caught the grove elders' attention.",sp=0},{t="Keepers of the Balance",b="Meeting Xyton Silverwind on the lower level of the great tree in Thendal Grove marks a novice's first step in their calling. To Silverwind, Zephras Isle's plants and animals form an intricate living whole that needs constant care and watchful balance. The path of fang, claw, feather, and branch calls for lasting mentorship, and this meeting begins a lifetime of stewardship.",sp=0}},faq={{q="Who sends the player to Xyton Silverwind?",a="After you help address the unruly vuldren around the grove, Rorian the Dayseeker hands you a folded parchment directing you to Xyton Silverwind.",al={"who gives a student of nature","quest giver","rorian"}},{q="Where is Xyton Silverwind located?",a="Xyton Silverwind is on the ground floor of the great tree in Thendal Grove, just behind Rorian the Dayseeker on Zephras Isle.",al={"xyton silverwind location","where is xyton","druid trainer location"},gp=true},{q="What is the purpose of this quest?",a="A Student of Nature introduces novice druids to Xyton Silverwind, their primary teacher and guide in keeping Zephras Isle's natural balance.",al={"why do this quest","quest goal","druid training start"},it="purpose"},{q="What does Xyton Silverwind teach novice druids about Zephras Isle?",a="Silverwind teaches that the island's plants and animals are interconnected and need active care and balance through the disciplines of fang, claw, feather, and branch.",al={"what does xyton say","zephras nature balance","druid role zephras"}},{q="What prerequisite must be completed before receiving this summons?",a="Initiates first complete Harmony in Balance for Rorian the Dayseeker, addressing the unruly vuldren population before receiving Silverwind's note.",al={"prereq quest","prior quest","before student of nature"},gp=true},{q="What is contained within the Folded Parchment?",a="The folded parchment is a note left by Xyton Silverwind. It directs the promising young druid to seek him beneath the canopy of the great tree for further training.",al={"folded parchment note","silverwind note","what is on parchment"},it="item"},{q="Why does Rorian the Dayseeker send you to Xyton Silverwind?",a="While you were out handling the local vuldren threat, the resident druid trainer, Xyton Silverwind, specifically left a message for you. Rorian is acting as the intermediary to ensure promising initiates receive proper instruction, urging you to heed Silverwind's counsel so you can master the druidic arts and preserve the natural balance.",al={"rorian motive","why send me to silverwind","why does rorian give you folded parchment"},it="motive",add="caa97f7a"}},ang={["class:Druid"]="As a druid, you begin lifelong training with Xyton Silverwind in the arts of the wild, the fang, and the branch."},kw={"druid","folded parchment","rorian the dayseeker","thendal grove","vuldren","xyton silverwind","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras","topic:druid"},m={start="Rorian the Dayseeker",["end"]="Xyton Silverwind",level="2",id=92485},src={"A Student of Nature"},fv=true}
E["quest:92532"] = {t="quest",n="The Warrior's Path",z="zephras",s="Rorian the Dayseeker sends you to Blademaster Ren in Thendal Village. She offers young warriors instruction and discipline to defend their people.",h="Rorian the Dayseeker sends you to Blademaster Ren in Thendal Village.",sec={{t="A Summons to the Watchtower",b="After restoring balance nearby, you return to Rorian the Dayseeker in Thendal Village. The village blademaster has noticed you, and Rorian gives you a crumpled note written by Ren herself. She asks you to come to her directly.\n\nRen waits in the village watchtower, high above the settlement. From there, she watches the island's borders and the recruits who may one day defend them.",sp=0},{t="The Mantle of Protection",b="Inside the watchtower, Blademaster Ren teaches you that combat takes more than brute strength. A warrior must lead, endure, and protect as the world grows more uncertain. Ren pledges to guide you as you hone your skills. Her rigorous training prepares you for the greater dangers threatening your home.",sp=0}},faq={{q="Who sends me to find Blademaster Ren?",a="After you finish work in Thendal Village, Rorian the Dayseeker directs you to Blademaster Ren. Ren asked Rorian to send you to her watchtower when you returned.",al={"who starts this","quest giver","rorian role"}},{q="Where can I find Blademaster Ren?",a="Blademaster Ren waits inside the watchtower in Thendal Village on Zephras Isle. She watches over the village and trains novice combatants.",al={"where is blademaster ren","ren location","thendal watchtower"},gp=true},{q="What is the Crumpled Note?",a="The Crumpled Note is Blademaster Ren's personal summons, delivered by Rorian. It asks you to read it and report to the Thendal Village watchtower for martial training.",al={"crumpled note","what does note say","ren note"},it="item"},{q="What does Blademaster Ren teach young warriors?",a="Blademaster Ren teaches vigilance, leadership, and protection. Warriors need the will to stand between danger and their people as the world shifts and dangers mount.",al={"ren teaching","what does ren train","warrior purpose"}},{q="Is this quest required for warrior training on Zephras Isle?",a="This introduces you to Blademaster Ren, your class trainer in Thendal Village, and shows where to return for martial techniques.",al={"do i have to do this","warrior trainer intro","is it mandatory"},gp=true},{q="What does Ren mean by 'may the winds guide you'?",a="Ren's blessing reflects the culture of Zephras Isle. It wishes travelers safe passage, focus, and fortune in unfamiliar and dangerous lands.",al={"may the winds guide you meaning","wind quote","ren farewell"}},{q="Why does Rorian the Dayseeker send me to Blademaster Ren?",a="Blademaster Ren personally asked Rorian to direct you to the watchtower the moment you returned to Thendal Village. With the world shifting and perilous trials ahead, Ren recognizes that burgeoning warriors require dedicated combat instruction and leadership guidance if your people are to survive the dangers to come. Rorian simply honors Ren's request to ensure you receive the training you need.",al={"why does rorian send me","rorian motive","why find blademaster ren"},it="motive",add="2d8c1194"}},ang={["class:Warrior"]="As a warrior, you begin your martial education in Thendal Village with Blademaster Ren as your mentor."},kw={"blademaster ren","crumpled note","rorian the dayseeker","thendal village","warrior's path","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Blademaster Ren",level="2",id=92532},src={"The Warrior's Path"},fv=true}
E["quest:92544"] = {t="quest",n="Al'Aketh Thugs",z="zephras",s="At the temple ruins near Thendal Grove, Al'Aketh cultists threaten travelers. Sent from the Shrine of Akir under High Priestess Lorthuna's orders, they harass wayfarers and force recruits into their ranks. Hanaa Nightwind asks you to break their hold and slay their commander.",h="At the temple ruins near Thendal Grove, Al'Aketh cultists threaten travelers.",sec={{t="Cultist Ruffians in the Ruins",b="Just southwest of Thendal Grove, ancient temple ruins have become dangerous for travelers. The Al'Aketh have seized the grounds and prey on people near the grove. Rangers stationed nearby suspect High Priestess Lorthuna sent the ruffians from the Shrine of Akir. They bully the people and force them to submit to the cult.",sp=0},{t="Malduko Cloudcrush",b="At the ruins, Malduko Cloudcrush rules through violence and fear. Brutes and newly indoctrinated neophytes obey him, making the temple an aggressive outpost at Thendal Grove's doorstep. Hanaa Nightwind hopes that striking down Cloudcrush and scattering his followers will break the cult's confidence. It will warn them that coercion will not be tolerated in these lands.",sp=0}},faq={{q="Who are the Al'Aketh?",a="The Al'Aketh are a fanatical cult operating on Zephras. High Priestess Lorthuna leads them from the Shrine of Akir. Her followers use intimidation and violence to force travelers and residents to join.",al={"what is the al'aketh","al'aketh cult","who are alaketh"},it="people"},{q="Why are the cultists attacking Thendal Grove?",a="The cultists have camped in temple ruins southwest of Thendal Grove. There, they ambush travelers leaving the area and terrorize people on the road. They hope to pressure locals into submitting to the cult.",al={"why are cultists here","why thendal grove","cultist motive"},it="conflict"},{q="Who is Malduko Cloudcrush?",a="Malduko Cloudcrush leads the Al'Aketh encampment at the temple ruins. Hanaa Nightwind calls him a monster. He directs the brutes and neophytes who prey on nearby roads.",al={"malduko","cloudcrush","who is malduko cloudcrush"},it="target"},{q="Who is Hanaa Nightwind?",a="Hanaa Nightwind is a Ranger guarding Thendal Grove. She remains at her post along the road and warns travelers of the nearby ambush. She depends on capable adventurers to clear the threat.",al={"hanaa","hanaa nightwind","quest giver"},it="identity"},{q="Who sent these cultists to the ruins?",a="Hanaa suspects High Priestess Lorthuna sent the cultists from the Shrine of Akir. Lorthuna oversees cult activities there.",al={"who commands them","cult leader","who sent malduko"},it="origin"},{q="What else can be found near the temple ruins?",a="An active Ley Line lies within the ancient ruins at the southwest end of the area, alongside the Al'Aketh encampment.",al={"ruins ley line","temple ruins secret","ruins southwest"},it="place"},{q="Why does Hanaa Nightwind want the Al'Aketh thugs cleared out?",a="The Al'Aketh cultists have camped dangerously close to Thendal Grove, harassing travelers along the roads and attempting to coerce local people into their zealous fold. Ranger Hanaa Nightwind wants to break their hold on the southwest ruins and send a bloody, unmistakable message that forces the surviving cultists to abandon the area.",al={"why kill the alaketh thugs","hanaa nightwind motive","why clear the temple ruins"},it="motive",add="b63e8692"},{q="Why can't Hanaa Nightwind deal with the cultists herself?",a="Hanaa must remain at her post to keep watch and warn unsuspecting travelers departing Thendal Grove before they wander into the cult's ambush. Though it takes all her restraint not to march into the ruins herself, she cannot abandon her duty at the grove's edge.",al={"why does hanaa need me","why doesn't hanaa fight them","why me alaketh thugs"},it="why_me",add="b6ccde37"}},kw={"al'aketh brute","al'aketh neophyte","al'aketh thugs","hanaa nightwind","high priestess lorthuna","malduko cloudcrush","shrine of akir","thendal grove"},rel={"quest:92471","zone:zephras"},m={start="Hanaa Nightwind",level="5",id=92544},src={"Al'Aketh Thugs"},fv=true}
E["quest:92597"] = {t="quest",n="Reading the Ley Lines",z="zephras",s="On Zephras Isle, young Skyborne seek the arcane currents beneath their feet. Falorne Fallwind sends them to Thendal Grove to feel power rising through the elemental plane.",h="On Zephras Isle, young Skyborne seek the arcane currents beneath their feet.",sec={{t="Arcane Currents of the Elemental Plane",b="Ley lines run beneath Zephras Isle, even through the elemental plane. Strange elementals and the hostile Al'Aketh cross the island as these buried currents rise toward the surface. For those with the bloodline and knowledge to channel them, the exposed lines open a path to raw arcane power.",sp=0},{t="Highborne Legacy",b="Falorne Fallwind urges initiates to claim their Highborne ancestry instead of seeking favor from wind spirits. The local Windshapers and the Al'Aketh both look to such spirits. Fallwind believes survival amid the elemental plane's harsh powers depends on mastering the arcane force beneath the ground, rather than asking foreign creatures for mercy.",sp=0},{t="Thendal Standing Stones",b="Northeast of the settlement, Thendal Grove's ancient standing stones mark a powerful meeting of ley lines. Roiling winds and Al'Aketh converts surround this exposed place. There, initiates can attune their senses to the ley line's pulse and unleash the full potential of their natural racial abilities.",sp=0}},faq={{q="Who gives the quest Reading the Ley Lines?",a="Falorne Fallwind on Zephras Isle gives young Skyborne this rite as they learn to channel their ancestral arcane power.",al={"quest giver","falorne fallwind","who starts reading the ley lines"},it="identity"},{q="Where is the ley line located?",a="The ley line lies northeast of the settlement, at the Thendal Standing Stones in Thendal Grove, amid hostile elementals and Al'Aketh converts.",al={"ley line location","where is thendal grove","thendal standing stones location"},it="place",gp=true},{q="Why are ley lines present in the elemental plane?",a="Arcane conduits run beneath the ground even in the elemental plane. The ley lines have begun to break through the surface, giving Skyborne direct access to powerful currents.",al={"arcane in elemental plane","ley lines elemental plane lore"},it="origin"},{q="How does Falorne Fallwind view the Windshapers?",a="Falorne disdains the Windshapers' reverence for air spirits. He sees it as weak supplication to uncaring elemental beings, no better than the Al'Aketh's worship.",al={"falorne on windshapers","windshapers lore","windshapers vs highborne"},it="conflict"},{q="What ability is required to channel the ley line?",a="You use the Skyborne racial ability Read Ley Line while standing at the energy convergence by the standing stones.",al={"read ley line ability","how to read ley line","racial ability used"},gp=true},{q="What benefit does tapping into ley lines provide?",a="Tapping an exposed ley line channels raw arcane energy into the user, heightening magical prowess. Its effects vary with the nature of the conduit.",al={"what do ley lines do","benefits of ley lines"},it="power"},{q="Why does Falorne Fallwind want you to read the ley lines?",a="Falorne believes that reclaiming your Highborne heritage and drawing directly from arcane ley lines is the only path to your people's salvation in the elemental plane. He views groups like the Windshapers and the Al'Aketh with contempt for debasing themselves before uncaring elemental entities. In his eyes, survival demands mastering latent magic rather than relying on fickle spirits.",al={"falorne fallwind motive","why read ley lines","falorne fallwind ley lines why"},it="motive",add="e5a629f0"}},ang={["race:Skyborne"]="As a Skyborne, you awaken your innate Highborne ancestry and learn to channel subterranean ley energy into your spellcasting.",["class:Mage"]="As a Mage, you can draw on exposed ley lines as a reservoir of raw power amid elemental storms."},kw={"al'aketh","falorne fallwind","highborne","ley lines","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle"},rel={"zone:zephras","topic:highborne","topic:elemental-plane"},m={start="Falorne Fallwind",level="4",faction="Alliance",id=92597},src={"Reading the Ley Lines"},fv=true}
E["quest:92598"] = {t="quest",n="The Gift of Skysight",z="zephras",s="On Zephras Isle, Ventaari Brightwish guides young Windshapers toward Skysight. At an Elemental Convergence, they awaken their perception and listen to the spirits.",h="On Zephras Isle, Ventaari Brightwish guides young Windshapers toward Skysight.",sec={{t="A Sacred Perception",b="Windshapers are born with a bond to the elemental forces that shape their world. They call its sacred faculty Skysight. This gift attunes mortal senses to the spiritual realm and reaches across the divide between the living and the unseen. In the wilds, a Windshaper can call on this inner vision. Near concentrated power, the bond grows stronger, bringing boons and wisdom whispered by the spirits.",sp=0},{t="The Convergence of Thendal Grove",b="Northeast of the settlement, ancient standing stones mark an Elemental Convergence in Thendal Grove. Raw energies gather at such places, where spirits linger. Ventaari Brightwish sends novices there to test their spiritual strength. Skysight grows with practice, like a faculty of body or mind. Windshapers must learn to read the elements' changing omens, for their people's survival depends on it.",sp=0}},faq={{q="What is the purpose of this quest?",a="Ventaari Brightwish sends novice Windshapers to an Elemental Convergence, where its power sharpens their Skysight.",al={"gift of skysight purpose","why do this quest","skysight training"},it="purpose"},{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish guides and mentors young Windshapers on Zephras Isle, teaching them to honor and hone their elemental heritage.",al={"ventaari","who is ventaari brightwish","brightwish"},it="identity"},{q="What is an Elemental Convergence?",a="An Elemental Convergence gathers spiritual energy, often around ancient standing stones. Elemental spirits linger there, and powers such as Skysight grow stronger.",al={"what is elemental convergence","elemental convergence lore","thendal grove convergence"},it="place"},{q="Where is the Elemental Convergence located?",a="The Elemental Convergence lies among the standing stones in Thendal Grove, northeast of the settlement on Zephras Isle.",al={"where is the convergence","thendal grove location","standing stones location"},it="place",gp=true},{q="Can Skysight be used anywhere?",a="A Windshaper can call on Skysight anywhere. At an Elemental Convergence, its power deepens and nearby spirits may offer further insight.",al={"can i use skysight anywhere","skysight outside convergence","where to use skysight"},it="power"},{q="Why is Skysight considered essential for survival?",a="Skysight lets mortals perceive elemental spirits and heed the elements' warnings. Ventaari says this sight is vital for meeting danger and preserving their people.",al={"why is skysight important","skysight survival","elements survival"},it="why_wanted"},{q="Why does Ventaari Brightwish want you to use Skysight at the convergence?",a="Ventaari Brightwish seeks to train you in your innate Windshaper heritage. Like a muscle, Skysight must be exercised at places of power such as the Elemental Convergence so you can learn to bridge the distance between the mortal and spiritual realms. She believes that communing with the spirits and heeding what the elements tell your people is crucial to your very survival.",al={"why does ventaari want this","ventaari brightwish motive","why use skysight here"},it="motive",add="d2ee972c"}},ang={["race:Skyborne"]="As Skyborne, you inherit Skysight from elemental patrons. It anchors your cultural and spiritual identity.",["class:Shaman"]="As a shaman, you know an Elemental Convergence as sacred ground, where the boundary between mortal will and the elemental planes grows thin.",["faction:Horde"]="As Horde, you rely on the Windshapers' foresight to face Zephras Isle's unmapped dangers."},kw={"elemental convergence","elemental spirits","skysight","standing stones","thendal grove","ventaari brightwish","windshaper","zephras"},rel={"npc:ventaari-brightwish","zone:zephras"},m={start="Ventaari Brightwish",level="4",faction="Horde",id=92598},src={"The Gift of Skysight"},fv=true}
E["quest:93552"] = {t="quest",n="Harvesting Windstones",z="zephras",s="At Thendal Grove, Dalia the Collector asks you to gather raw windstones before their power fades. The ancient elemental energies of Zephras Isle are slowly dwindling.",h="At Thendal Grove, Dalia the Collector asks you to gather raw windstones before their power fades.",sec={{t="A Fading Island",b="Zephras Isle still draws on wind magic, but its natural defenses are failing. Centuries ago, the wind elementals who shared the island with its elves vanished. Since then, the magic that sustains the land and its great anchor pylons has weakened. So Thendal Grove’s residents need every reserve of raw energy they can secure.",sp=0},{t="The Value of Windstones",b="Blue crystalline windstones lie scattered through Thendal Grove. Their brittle shells hold dense wind magic from ages past. They cannot sustain the island forever, yet they give its elves a dependable source of arcane power. Gathering raw clusters remains vital to daily life.",sp=0}},faq={{q="What are windstones?",a="Windstones are blue crystalline deposits scattered around Thendal Grove. They hold concentrated raw wind energy, which the elves of Zephras Isle gather as magical fuel.",al={"raw windstone","windstone cluster","blue crystals"},it="power"},{q="Who is Dalia the Collector?",a="Dalia the Collector is an elven collector stationed in Thendal Grove on Zephras Isle. She organizes the gathering of vital raw resources, especially windstones, to support the island’s dwindling magical reserves.",al={"dalia","dalia zephras","collector dalia"},it="identity"},{q="Why is the magic on Zephras Isle fading?",a="Centuries ago, the wind elementals who lived alongside the local elves vanished. Since then, the great anchor pylons’ magic, which sustains the island, has slowly drained away.",al={"zephras losing magic","fading magic zephras","anchor pylons"},it="threat"},{q="Where did the wind elementals go?",a="No one knows where the wind elementals went. They vanished several centuries ago, leaving the island to slowly exhaust its remaining elemental reserves.",al={"missing elementals","where are wind elementals","elementals vanished"},it="history"},{q="What are the anchor pylons?",a="The great anchor pylons are ancient structures on Zephras Isle, imbued with powerful magic that sustains the land. Since the elementals vanished, that sustaining power has gradually weakened.",al={"great anchor pylons","anchor pylon lore"},it="place"},{q="Where do you find raw windstones?",a="Raw windstones are scattered across Thendal Grove on Zephras Isle, where they appear as glowing blue crystalline outcrops.",al={"windstone location","thendal grove crystals"},it="place",gp=true},{q="Why does Dalia the Collector want Windstone Clusters?",a="Dalia seeks Windstone Clusters because Zephras Isle relies on their magical power to endure. Ever since the wind elementals vanished centuries ago, the sustaining magic that once nourished the island has been slowly waning. To the local elves, whose lives and culture remain deeply tied to arcane energy, collecting these crystallized winds provides a vital and dependable energy source to replace what the failing anchor pylons can no longer supply.",al={"why dalia wants windstones","dalia collector motive","why harvest windstones"},it="motive",add="0a83a06c"},{q="What are Windstone Clusters used for?",a="Windstone Clusters hold the raw, concentrated energy of the winds themselves. Because the ancient magical anchor pylons on Zephras Isle are losing their potency over time, the isle's inhabitants harness these crystallized clusters as a reliable alternative source of power to sustain their community and maintain their essential connection to magical energy.",al={"windstone cluster use","what is windstone cluster for","why windstone clusters"},it="item",add="33ac4299"}},ang={["class:Mage"]="As a Mage, you can see the elemental power held in windstones and how fragile magical ecosystems become when their elemental sources vanish.",["profession:Mining"]="As a miner, you gather valuable minerals and crystals from the wilds of Zephras Isle, including raw windstones."},kw={"anchor pylons","dalia","dalia the collector","thendal grove","wind elementals","windstone cluster","windstones","zephras isle"},rel={"zone:zephras"},m={start="Dalia the Collector",level="4",id=93552,ri={"Windstone Cluster"}},src={"Harvesting Windstones"},fv=true}
E["quest:93746"] = {t="quest",n="A Firm Response",z="zephras",s="Ayessa Dawnsinger answers the High Order’s intrusion on Zephras Isle with force. She sends you after Belathaan Brightwish on the road north to the Shrine of Akir, to make the Windshapers’ boundaries clear.",h="Ayessa Dawnsinger answers the High Order’s intrusion on Zephras Isle with force.",sec={{t="Drawing the Line",b="The Windshapers of Zephras Isle will not accept the High Order’s secretive scrutiny. Their warnings have gone unheeded, so Ayessa Dawnsinger escalates the dispute. She sends you to intercept Belathaan Brightwish on the lonely road north to the Shrine of Akir, away from prying eyes in town.",sp=0},{t="Storms on the Road",b="Belathaan Brightwish travels north toward the ancient Shrine of Akir, and his purpose is unclear. When you confront him on the secluded road, he turns hostile, and Living Storms join the fight. Defeating the elementals and humbling Belathaan sends the High Order a clear message: the Windshapers answer interference with force.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger belongs to the Horde-aligned Windshapers on Zephras Isle. She protects their domain and acts ruthlessly against intruders who meddle in their affairs.",al={"ayessa dawnsinger","who gives a firm response","ayessa"},it="identity"},{q="Who is Belathaan Brightwish?",a="Belathaan Brightwish is tied to the High Order. Ayessa Dawnsinger targets him to intimidate the organization after he is spotted heading alone toward the Shrine of Akir.",al={"belathaan brightwish","belthaan","who is belathaan"},it="target"},{q="What is the High Order?",a="The High Order is a faction on Zephras Isle whose activities conflict with those of the local Windshapers. It keeps probing into their affairs despite explicit warnings.",al={"high order","the high order lore","what is the high order"},it="people"},{q="Where is the Shrine of Akir located?",a="The Shrine of Akir lies north of town on Zephras Isle. Belathaan is intercepted on the secluded road that leads there.",al={"shrine of akir","where is shrine of akir","shrine akir zephras"},it="place",gp=true},{q="Why does Ayessa want Belathaan beaten rather than killed?",a="Ayessa wants Belathaan beaten to send a message without starting a total war. She hopes he will return to his superiors with fear and respect for the Windshapers’ boundaries.",al={"kill belathaan","why spare belathaan","why just bruises"},it="motive"},{q="What are the Living Storms encountered during this task?",a="Living Storms are elemental entities that appear during the confrontation with Belathaan on the road. They reflect Zephras Isle’s volatile elemental energies.",al={"living storms","what are living storms"},it="threat"},{q="Why does Ayessa Dawnsinger want Belathaan confronted?",a="The High Order has repeatedly meddled in the affairs of the Windshapers, ignoring previous warnings to respect their territory and practices. Ayessa believes diplomatic words are no longer enough. By intercepting Belathaan on the road and giving him a harsh thrashing, she hopes to send an unmistakable message back to his superiors that the Windshapers will enforce their boundaries by force if necessary.",al={"why confront belathaan","ayessa motive","why send message to high order"},it="motive",add="3180a0eb"}},ang={["faction:Horde"]="As a member of the Horde on Zephras Isle, you help secure its positions and keep rivals like the High Order from encroaching on allied interests.",["class:Shaman"]="As a shaman, you face Living Storms amid the turbulent, untamed elemental air magic found across Zephras Isle."},kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","living storms","shrine of akir","windshapers","zephras isle"},rel={"npc:ayessa-dawnsinger","zone:zephras"},m={start="Ayessa Dawnsinger",level="9",faction="Horde",id=93746},src={"A Firm Response"},fv=true}
E["quest:94414"] = {t="quest",n="The Anchors of Zephras",z="zephras",s="On Zephras Isle, Halaan Hawk-Eye asks you to watch the ancient anchor pylons that hold the island aloft. Their magic has begun to waver, and the wind spirits' blessing may no longer be steady.",h="On Zephras Isle, Halaan Hawk-Eye asks you to watch the ancient anchor pylons that hold the island aloft.",sec={{t="Tethers of the Isle",b="Wind spirits gave Zephras's ancient anchor pylons the power to bind and sustain the floating island. Their magic keeps the land steady amid the churning skies. From afar, the towering monoliths look untouched. Yet the island depends on the wind spirits' continuing blessing.",sp=0},{t="A Disturbing Shift",b="The anchor pylons look proud and undamaged, yet their magic has grown erratic. Halaan Hawk-Eye says the harmony that sustains them has become unstable and uncertain. No clear sign of physical harm appears. Those who watch over the groves have reason to fear what threatens the isle.",sp=0},{t="Halaan's Gift",b="Halaan Hawk-Eye cannot use skysight to peer between worlds, nor can he tap Zephras's deep ley lines. His gift is natural vision sharp enough to reach immense distances. He lends that sight to newcomers, so they can study the distant pylons and watch for changes in their homeland's fate.",sp=0}},faq={{q="What are the anchor pylons on Zephras?",a="The anchor pylons are ancient structures the wind spirits gave to Zephras. They bind and sustain the island, keeping it stable above the surrounding world.",al={"what are the anchors","zephras anchor pylon","what is an anchor pylon"},it="purpose"},{q="What is wrong with the anchor pylons?",a="The pylons show no obvious physical damage, but their stabilizing magic has grown unstable and inconsistent. The cause remains unknown.",al={"why are anchors failing","anchor pylon problem","what happened to the anchors"},it="threat"},{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye watches over the groves of Zephras Isle. His natural sight reaches great distances, and he watches over the land's well-being.",al={"halaan lore","who is halaan"},it="identity"},{q="What is Halaan's gift?",a="Halaan's gift is exceptionally sharp sight over great distances. It is natural vision, unlike skysight or the power to tap Zephras's deep ley lines.",al={"halaan's gift","how does halaan see far"},it="power"},{q="What is skysight?",a="Skysight is a mystical perception that lets certain practitioners peer between worlds, far beyond ordinary vision.",al={"what is the skysight","skysight meaning"}},{q="Where does the magic powering the pylons come from?",a="The wind spirits gave the anchor pylons to Zephras. Halaan says they bind and sustain the island, but does not explain where their continuing power comes from.",al={"who made the pylons","anchor pylon origin"},it="origin"},{q="Why does Halaan Hawk-Eye want you to look at the anchor pylon?",a="Halaan Hawk-Eye watches over the grove and cares deeply about the health of Zephras. The ancient anchor pylons, gifts from the spirits of the winds, bind and sustain the island, but their magic has recently grown unstable and inconsistent. Though they appear physically undamaged, Halaan offers to share his far-reaching vision so you can witness the pylons firsthand and understand the delicate state of your homeland.",al={"halaan motive","why look at anchor pylon","why does halaan want this"},it="motive",add="61bc2f74"}},ang={["class:Shaman"]="As a shaman, you know the wind spirits' blessing sustains the anchor pylons. Their unstable magic calls for an elemental's attention.",["class:Mage"]="As a mage, you can recognize Halaan's keen eyesight as a natural gift."},kw={"anchor pylon","anchors of zephras","halaan hawk-eye","ley lines","skysight","wind spirits","zephras"},rel={"npc:halaan-hawk-eye","zone:zephras"},m={start="Halaan Hawk-Eye",level="2",id=94414},src={"The Anchors of Zephras"},fv=true}
E["quest:96638"] = {t="quest",n="The Adventurer",z="zephras",s="On Zephras Isle, The Adventurer leaves Thendal Grove for the road to Shen'dar Village. Aetheen of the Gales sends newly seasoned wanderers southwest to meet Raan Wildwind, a veteran camper who knows the wilds.",h="On Zephras Isle, The Adventurer leaves Thendal Grove for the road to Shen'dar Village.",sec={{t="Leaving the Grove",b="Thendal Grove offers shelter, but Zephras Isle beyond it remains wild and perilous. Aetheen of the Gales watches over the initiates and knows when a traveler is ready to leave familiar ground. Those seeking fame, fortune or purpose have outgrown the grove's sheltered bounds.",sp=0},{t="A Guide on the Road",b="Raan Wildwind has made camp southwest of Thendal Grove, along the road to Shen'dar Village. He has spent time facing the dangers beyond the safe haven. For wanderers setting out from the grove, Raan offers practical counsel on surviving the open roads.",sp=0}},faq={{q="Who sends you to find Raan Wildwind?",a="Aetheen of the Gales sends you from Thendal Grove to find Raan Wildwind. After you prove yourself in the surrounding woods, she points you toward someone who knows the wider isle firsthand.",al={"who gives the adventurer","who starts the adventurer quest","aetheen quest"}},{q="Where is Raan Wildwind located?",a="Raan Wildwind has made camp southwest of Thendal Grove, along the main road to Shen'dar Village.",al={"raan wildwind location","where is raan","how to find raan wildwind"},it="place",gp=true},{q="What is the purpose of this task?",a="You leave Thendal Grove's safe haven and meet a guide to the challenges farther across Zephras Isle.",al={"why do the adventurer","purpose of quest the adventurer","what does raan teach"},it="purpose"},{q="What prerequisite must be completed before receiving this quest?",a="Before Aetheen of the Gales sends you to Raan Wildwind, you must complete the task concerning the Foul Matriarch.",al={"the adventurer prereq","requirements for the adventurer"},gp=true},{q="Is Shen'dar Village safe for travelers?",a="Shen'dar Village lies beyond Raan's camp, at the end of the road southwest from Thendal Grove. It is a notable settlement, but take care on the roads and in the surrounding wilds.",al={"is shendar safe","what is shendar village"},it="danger"},{q="Who is Raan Wildwind?",a="Raan Wildwind is a wanderer who traveled beyond Thendal Grove and made camp outside Shen'dar Village. He offers practical advice and tasks to newcomers heading down the road.",al={"raan lore","who is raan wildwind"},it="identity"},{q="Why does Aetheen of the Gales send you to find Raan Wildwind?",a="Aetheen recognizes that more wanderers are venturing beyond the safety of Thendal Grove in search of glory and fortune. Knowing the wilderness poses great danger to the inexperienced, Aetheen wants you to seek out Raan Wildwind—a fellow traveler camped near Shen'dar Village—to learn practical wisdom and survival lessons that will keep you alive during your journeys across the isle.",al={"why does aetheen send you","aetheen of the gales motive","why meet raan wildwind"},it="motive",add="dc12ab9c"}},ang={["race:Skyborne"]="As a young Skyborne leaving Thendal Grove's sheltered canopy, you meet Raan Wildwind as your first step into the wider wilds of your island home."},kw={"aetheen of the gales","raan wildwind","shen'dar village","the adventurer","thendal grove","zephras isle"},rel={"quest:92470","quest:92471","zone:zephras"},m={start="Aetheen of the Gales",["end"]="Raan Wildwind",level="6",id=96638},src={"The Adventurer (Zephras Isle)"},fv=true}
E["subzone:calmbreeze-inn"] = {t="subzone",n="Calmbreeze Inn",z="zephras",s="In Shen'dar Village and Valaanar, Calmbreeze Inns offer travelers rest on Zephras Isle. Both provide shelter and local services.",h="In Shen'dar Village and Valaanar, Calmbreeze Inns offer travelers rest on Zephras Isle.",sec={{t="Rest on the Isle",b="Travelers can rest at the Calmbreeze Inns on Zephras Isle. Coriella Calmbreeze runs the inn in Shen'dar Village, where island tradesfolk gather. There, you can find mentors in herbalism, skinning, and enchanting.\n\nAcross the way, the Valaanar inn welcomes local wayfarers and shelters rare curios. Upstairs, an audio crystal holds a recording of the ancient rebellion in Eldre'Thalas.",sp=0}},faq={{q="Where are the Calmbreeze Inns located?",a="Calmbreeze Inns are found in Shen'dar Village and Valaanar on Zephras Isle.",al={"calmbreeze inn location","where is calmbreeze inn","calmbreeze inn map"},it="place",gp=true},{q="Who runs the inn in Shen'dar Village?",a="Innkeeper Coriella Calmbreeze runs the Shen'dar Village inn and welcomes island residents and travelers.",al={"calmbreeze innkeeper","who runs calmbreeze inn"},it="residents"},{q="What trainers can be found at the inn?",a="At the Shen'dar Village inn, Halassa Fernbreeze teaches Herbalism, Mendalass Tattermend teaches Skinning, Nasalanna Windsinger teaches Enchanting, and Miriann Mistblade teaches Rogue training.",al={"calmbreeze trainers","shen'dar inn trainers"},gp=true},{q="What is the audio crystal found upstairs in Valaanar?",a="Upstairs in the Valaanar inn, an audio crystal holds Part 3 of 'The Rebellion In Eldre'Thalas', recounting events from the ancient Highborne city.",al={"valaanar audio crystal","the rebellion in eldre'thalas crystal"},it="item"},{q="What is the Calmbreeze Inn?",a="The Calmbreeze Inn refers to the network of inns serving travelers across Zephras Isle, with locations established in both Valaanar and Shen'dar Village. These establishments serve as vital community hubs, providing weary travelers with a place to rest, meet local tradesfolk and trainers, and gather news from across the island.",al={"what is calmbreeze inn","calmbreeze inn lore","about calmbreeze inn"},it="place",add="043ce63b"},{q="Is the Calmbreeze Inn dangerous?",a="No. The Calmbreeze Inns are peaceful sanctuaries within their respective settlements of Shen'dar Village and Valaanar. They are filled with friendly citizens, innkeepers, and craft trainers rather than hostile threats.",al={"is calmbreeze inn safe","calmbreeze inn dangers","danger at calmbreeze inn"},it="danger",add="c8344be2"}},ang={["profession:Herbalism"]="As an herbalist in Shen'dar Village, you can find Halassa Fernbreeze inside the Calmbreeze Inn and hone your gathering craft.",["class:Rogue"]="As a rogue in Shen'dar Village, you can seek instruction from Miriann Mistblade at the Calmbreeze Inn hearth."},kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar village","valaanar","zephras isle"},rel={"zone:zephras"},src={"Calmbreeze Inn"}}
E["zone:zephras"] = {t="zone",n="Zephras Isle",z="zephras",s="On Zephras Isle, the Skyborne face a homeland slowly coming apart. Air elementals once shared the island with them, but those guardians vanished and the magic that holds the land aloft is fading. Refugees arrive from Anvilas and Siroccas as those islands crumble.",h="On Zephras Isle, the Skyborne face a homeland slowly coming apart.",sec={{t="A Realm Aloft",b="In skywall, the elemental plane of air, the Skyborne have lived on Zephras Isle for generations. Native air elementals once helped preserve the magical currents that keep the island aloft. Several centuries ago, those elementals vanished. Without their presence, the enchantments beneath the land have slowly weakened, and Zephras has begun to fracture.",sp=0},{t="Severed Horizons",b="Anvilas and Siroccas once drifted through skywall alongside Zephras, and the Skyborne made homes on all three islands. When the elementals vanished, communication between the islands ended. Now refugees from the crumbling neighbors have reached Zephras seeking safety. They report that the land beneath them on Anvilas and Siroccas is breaking apart.",sp=0},{t="Threshold to Azeroth",b="As Zephras decays, the Skyborne look beyond skywall toward Azeroth. Airships now set out from the skydocks of valanaar to make rare links with the mortal realm. Their voyages reach the outskirts of Dalaran in the alterac mountains and skywatcher plateau in Mulgore.",sp=0}},faq={{q="Where is Zephras Isle located?",a="Zephras Isle floats within skywall, the elemental plane of air, rather than on Azeroth. Clouds and wind currents surround the island in that ethereal realm.",al={"zephras isle location","where is zephras","what plane is zephras on"},it="place"},{q="Why is Zephras Isle falling apart?",a="Native air elementals once lived alongside the Skyborne and helped sustain Zephras Isle. They vanished several centuries ago, and the island's magical foundations have slowly weakened since.",al={"why is zephras collapsing","zephras isle destruction","dying island"},it="ruin"},{q="What are Anvilas and Siroccas?",a="Anvilas and Siroccas are neighboring floating island homes of the Skyborne in skywall. Contact with both ended when the elementals vanished, and refugees now report that the islands are collapsing.",al={"anvilas","siroccas","other skyborne islands"},it="place"},{q="How do people travel between Zephras Isle and Azeroth?",a="The Skyborne launch airships from the skydocks at valanaar and cross into Azeroth. They reach the outskirts of Dalaran in the alterac mountains and skywatcher plateau in Mulgore.",al={"how to leave zephras","zephras airships","travel to azeroth"},it="place"},{q="Who are the Skyborne?",a="The Skyborne have made their homes on Zephras Isle and its sister sky-realms for generations. Their floating island homeland is slowly breaking apart as its sustaining magic fades.",al={"skyborne race","who lives on zephras"},it="residents"},{q="Who lives on Zephras Isle besides the Skyborne?",a="Local bandits, cavern-dwelling nightclaws, and beasts live on Zephras Isle. They can be found in places such as the Shriekling Den and Nightclaw Cavern.",al={"zephras inhabitants","enemies on zephras"},it="residents"},{q="What is Zephras Isle?",a="Zephras Isle is a soaring floating landmass located within Skywall, the Elemental Plane of Air. Millennia ago, night elf exiles fleeing persecution in Eldre'Thalas bargained with native wind spirits, who lifted the island into the heavens to keep them safe. It serves as the ancestral sanctuary of their descendants, the Skyborne.",al={"what is zephras","about zephras isle","zephras isle info"},it="place",add="1fd88046",nx={10}},{q="What happened at Zephras Isle?",a="Zephras Isle was raised into Skywall after high elven ancestors broke away from Prince Tortheldrin's bloody reign in Eldre'Thalas. The Skyborne lived in harmony with air elementals for thousands of years, but centuries ago, those elemental patrons vanished without explanation. Without their continuous magic, the pylons anchoring the island began to decay, and refugees from neighboring collapsing islands have fled here while internal factions vie for dwindling resources.",al={"zephras history","what happened here zephras","zephras lore"},it="history",add="7ea7c85c"},{q="Is Zephras Isle dangerous?",a="Yes. Beyond the looming physical threat of the island itself destabilizing and tumbling from the skies, the disappearance of elemental protectors has left the land chaotic. Bandit encampments, hostile wildlife dens, and volatile political friction between the High Order, Windshapers, and Al'Aketh all make travel outside fortified settlements perilous.",al={"is zephras dangerous","zephras threats","dangers on zephras"},it="danger",add="70a3c6ae"},{q="Where is the isle compared to the rest of Azeroth?",a="Zephras Isle does not rest upon Azeroth's surface; it drifts within Skywall, a separate dimensional domain crafted by the titan-forged to contain chaotic air elementals. The only physical connections between the isle and the mortal world below are specialized airships that dock at Valanaar and travel across the boundary to points like Dalaran and Mulgore.",al={"where is zephras to azeroth","is zephras in azeroth","zephras location compared to azeroth"},it="place",add="b4875d06"},{q="Who are the Al'Aketh?",a="The Al'Aketh are one of the rival factions contending for dominance on Zephras Isle alongside the High Order and the Windshapers. As the pylons anchoring the island fail and survival grows desperate, the Al'Aketh actively vie for supremacy and control over the isle's remaining mystical resources.",al={"what are the alaketh","al'aketh faction","who is alaketh"},it="threat",add="2c89f95d"},{q="Am I leaving the isle eventually?",a="Yes. While Zephras Isle serves as your home and starting training ground, airships depart from the skydocks at Valanaar across planar rifts to mainland Azeroth, connecting directly to Dalaran in the Alterac Mountains and Skywatcher Plateau in Mulgore.",al={"will i leave zephras","leaving zephras isle","can we go to azeroth"},it="next_step",add="6e14d755"},{q="How did I end up in Zephras Isle?",a="You were born into the Skyborne, the shen'dorei who dwell upon this floating haven high within Skywall, the Elemental Plane of Air. Millennia ago, your ancestors fled the purge of Prince Tortheldrin in Eldre'Thalas and struck a pact with wind spirits who raised this sanctuary into the heavens. While other sibling islands like Anvilas and Siroccas crumble or fade from reach, Zephras Isle has been your home from the start. You begin your journey here among your own people.",al={"how did i get here","how did i reach zephras isle","why did i wake up here","where did i come from"},it="arrival",rc="Skyborne",add="19470e71"},{q="What am I supposed to be doing in Zephras Isle?",a="Your home is crumbling beneath your feet. Centuries ago, the benevolent air elementals vanished, and the arcane pylons that bind Zephras Isle together are losing their power. Refugees flood in from collapsing outer isles while rival factions, including the High Order, the Windshapers, and the Al'Aketh, squabble over what remains. You must aid your people, quell internal threats and wild beasts, help stabilize the failing magics, and ultimately seek a passage down to Azeroth before the island falls.",al={"what should i be doing here","what is my goal here","what am i doing on zephras isle","why am i here"},it="purpose",rc="Skyborne",add="5dae6f41"}},ang={["race:Skyborne"]="As a Skyborne, Zephras Isle is your ancestral home and starting ground. Its beauty remains even as the land collapses and elemental power fades.",["class:Shaman"]="As a Shaman, you know Zephras Isle lies within the Elemental Plane of air. Its fading elemental power shows what happens when the spirits that sustain an elemental land disappear."},kw={"airships","anvilas","elemental plane","siroccas","skyborne","skywall","valanaar","windstones","zephras"},rel={"topic:skyborne","topic:skywall","topic:elemental-plane","npc:ventaari-brightwish","quest:93552","zone:alterac","zone:mulgore","subzone:dalaran"},m={levels="1-12"},src={"Zephras Isle"}}
